INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'438',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='14'),'Gamingrommet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Lokalet er 24m2, utstyrt med fem gamingstasjoner. Bruk av utstyr krever ekstra opplæring/kunnskaper. Lokalet ligger i sammenheng med lydstudioet vårt og de to bookes samtidig.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'931',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='172'),'Rom 19 (219)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='16'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'812',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='143'),'Svømmebasseng',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='15'),NULL,NULL,'16,5 x 8,5m',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'791',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Grupperom (Rom 2008) (UKEDAGER FRA KL. 16.00)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Middels grupperom (11 m2) ved biblioteket, for 6 personer, med skjerm og teleslynge. 2. etasje. Tilgjengelig for booking: Mandag 16:00:00 22:00:00 Tirsdag 16:00:00 22:00:00 Onsdag 16:00:00 22:00:00 Torsdag 16:00:00 22:00:00 Fredag 16:00:00 22:00:00 Lørdag 10:00:00 22:00:00 Søndag 10:00:00 22:00:00',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'452',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='46'),'TUBAKUBA',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='13'),NULL,NULL,'Informasjon om Tubakuba Tubakuba er et tilbud til barnefamilier i Bergen kommune ( familier med barn under 12 år ). Du finner hytten i skogkanten på Fløyen med byens fineste utsikt. Hytten er enkelt utstyrt. Du finner 4/5 soveplasser i 3 ulike høyder uten madrasser. For å overnatte på Tubakuba må du derfor pakke med deg alt fra varmt tøy, noe mykt å ligge/sitte på, noe å lage mat på, hodelykter og så videre. I Tubakuba finner du brisker til å sove på, en vedovn og kost og feiebrett. Egen medbrakt ved må benyttes. Regler for lån av Tubakuba: Leietaker (den som søker) er ansvarlig for bruken av hytten. Nøkkel til hytten hentes hos Innbyggerservice i Kaigaten 4. Nøkkel må hentes og leveres innenfor kontorets åpningstid, mandag-fredag mellom kl 08:00 og 15:00. Nøkkel hentes tidligst dagen før du skal låne hytten, og leveres tilbake samme sted første virkedag etter lån av hytten. Innbyggerservice har stengt helger/helligdager. Skal hytten leies lørdag eller søndag må nøkkel hentes senest klokken 15:00 på fredag. Får vi ikke nøkkelen i retur blir leietaker fakturert. Det vil bli krevd legitimasjon for å hente nøkkel, og den som henter er ansvarlig for at den blir levert tilbake. Innsjekk er tidligst kl.15:00 og utsjekk er innen kl.12:00. Hytten leies ikke ut i perioden mellom to reservasjoner. Om du ikke kan bruke hytten må du gir beskjed slik at hytten kan lånes ut til andre. For å unngå karantene til neste gang du kan låne hytten må du gi beskjed minimum 24 timer før innsjekk. Åpen ild er strengt forbudt ut over bruk av vedovn, dette gjelder også stearinlys. Tennvæske eller annet som er lett antennelig skal ikke settes igjen i hytten. Av sikkerhetsmessige årsaker tillater vi ikke bålbrenning i området rundt hytten. Det er ikke lov til å drikke alkohol i Tubakuba. Det er ikke lov til å bruke utesko inne. Utesko skal du sette fra deg i «tuben» eller på steinhellene rett innenfor døren. På grunn av allergier har du ikke lov til å ha hund i hytten. Husk å rydde/koste hytten og ta med deg alt søppel. Det er kun mulig å bestille overnattinger for inneværende kalendermåned og to måneder fram i tid. Ny periode blir lagt ut ved overgang til ny kalendermåned, den 1. i hver måned . Det er kun tillatt med to reservasjoner pr husstand pr år. B ymiljøetaten tar forbehold om at bookingene kan endres dersom det oppstår spesielle eller uforutsette situasjoner.','Nøkkelen hentes hos Innbyggerservice i Kaigaten 4. Åpningstider: Mandag: 8:00-15:00 Tirsdag: 8:00-15:00 Onsdag. 8:00-15:00 Torsdag: 8:00-15:00 Fredag: 8:00-15:00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'609',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='132'),'Møterom garderobebygg',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Møterom på ca 60 kvm med skjerm på veggen, bord og stoler til ca 30 personer samt kjøkkenfasiliteter. Møterom for idrettens bruk. Leies ikke ut som selskaps- eller forsamlingslokale.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'696',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='140'),'Mat og helse (160)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='5'),NULL,NULL,'Mat og helse er rom 160 i branntegning. Mat og helse er skolekjøkkenet vårt. Dette leies ofte ut til bursdager i kombinasjon med musikkrommet. Det er 16 plasser der, men dette kan suppleres med bord og stoler som står i garderoben utenfor musikkrom. Det er også 4 komfyrer og 2 oppvaskmaskiner Oppvaskmaskin settes på når dere er ferdig, og vi tømmer den dagen etter.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
