INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'113',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='7'),'Møterom 3',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Møterom til mindre grupper, har skyvedør inn til tilstøtende rom Møterom 1 og 3 kan slåes sammen til ett enkelt rom med følgende mengdebegrensninger: 70 personer u/ møbler 50 personer m/møbler 20 personer hvis loppemarked For leievilkår, priser, etc, se "Nordnes bydelshus" (bygg/anlegg).',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'118',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='69'),'UHU 2 (drop in øving)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Øvingslokale Rommet er utstyrt med: 2 gitarforsterkere (minimum) 1 bassforsterker 1 trommesett (1 skarp, 1 dollar, 3 tammer, hihat og 3 cymbaler) 2 mikrofoner m/stativ (minimum) Kabel til telefon/data (minijack) 1 PA-anlegg Gitarer, keys og trommestikker bør du ta med selv. Passer best for band med opp til fem personer. Drop-in booking. Velg tidspunkt selv. Anbefaler de som øver ofte å booke et fast tidspunkt, f.eks. en gang i uken for å slippe å sende inn søknad for hver øving. PS. Book minst to dager i forveien av ønsket tid, helst enda tidligere. PPS. Har du aldri øvd her før, book så tidlig i forkant som mulig, da du trenger både nøkkel og befaring før du kan øve. Kr. 75,- per påbegynt økt (3 timer). Gratis for ungdom i skolealder (t.o.m. videregående). Ungdom vil bli prioritert.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
