INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'51',k.id,NULL,'Kjøkken',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Kjøkkenet kan tilknyttes leie av alle rom i Åsane kultursenter. Kjøkkenet egner seg ikke til matlaging, men som anretningskjøkken, eventuelt til lett oppvarming av ferdig tilberedt mat. Leietakere må selv vaske og rydde på plass alt utstyr som er brukt. Kjøkkenet inneholder: Dekketøy for 150 personer Stor kaffekoker Dobbel kaffetrakter Vannkoker Enkel komfyr Mikrobølgeovn Kjøleskap med fryseskap Industrioppvaskmaskin Husholdningsoppvaskmaskin',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'468',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='70'),'Øvingsbinge 07 (Fast)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Per i dag leies 12 musikkbinger ut til band med eget utstyr. 3-4 band deler en musikkbinge og leien reguleres etter antall band. Er dere 3 band som deler lokale betaler dere 1875,- i måneden. Er dere 4 band er månedsleien 1375,-.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'371',k.id,NULL,'workshop',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Workshop. Rommet inneholder flere symaskiner, datamaskiner ( til bl.annet filmredigering, billedbehandling m.m ), projektor m.m. Kan brukes til ulike kurs, workshops og samlinger.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'48',k.id,NULL,'Halvan',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Halvan er en av kinosalene som var i huset fra opprinnelsen. Brukes i dag blant annet til teaterforestillinger, små konserter, foredrag og møter. Salen har 60 sitteplasser, og et lite backstageområde. Det er fastmontert projektor og CD/DVD-spiller, og et enkelt lydanlegg, men ved bruk av PC må denne medbringes av leietaker Halvan er også tilrettelagt for dans, med dempet gulv, speilvegg og mobile ballettbarrer.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
