INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'381',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='98'),'Møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Dette er et lite møterom, ca 15 kvm, med møtebord og stoler. Plass til maks 15 personer. Rommet er utstyrt med prosjektor og lerret.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'44',k.id,NULL,'Helan (Storsal)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Helan er Åsane kultursenter sin storsal. Her er det plass til 150 personer, ved borddekking cirka 100 personer. Rommet kan brukes til øvingsrom for forskjellige kulturaktiviteter, forestillinger, utstillinger, møter og seminarer. Det brukes også til private arrangementer som barnedåp og konfirmasjon, men leies dessverre ikke ut til brylluper og større festlige anledninger. Helan har fastmontert projektor med lerret, CD-/DVD-spiller og et enkelt lydanlegg med teleslynge. Ved bruk av pc må denne medbringes av leietaker. Det står også et piano i rommet. Salen har også en speilvegg som kan benyttes i forbindelse med danseøvinger eller lignende aktiviteter. I Helan er det 30 bord og 150 stoler. Leietaker har selv ansvar for å plassere bord og stoler som ønsket, og å rydde etter arrangement.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
