INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'93',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='10'),'Møterom - Fanafjellet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Stort møte- og aktivitetsrom med plass til opptil 40 personer. 61m2. Lyd- og AV-utstyr med fjernkontrollbetjening. Kjøkkenkrok med kjøleskap, oppvaskmaskin, kaffetrakter, kopper, fat og bestikk til 50 personer. Ingen kokemuligheter. Leietaker må selv ha med forbruksvarer som kaffe/te, kaffefilter, etc. Inngang via hovedinngangen, deretter heis eller trapp til plan 2. Priser: Lag/org med kulturrelaterte aktiviteter gratis i ukedagene Andre Kr. 300,- pr time Praktisk informasjon ved utleie av kulturlokalene Kulturlokalene er først og fremst beregnet til kulturaktivitet for barn og unge Kulturhusene er ubetjente, dette medfører at leietakere må rigge og rydde selv Lokalene (ressursene) brukes av flere organisasjoner daglig, vi gjør oppmerksom på at renhold utføres en gang pr dag, mandag til og med fredag. Det blir ikke utført renhold lørdag og søndag Ta med utskrift av innvilget søknad ved utlevering av nøkkelkort hos Fana og Ytrebygda kulturkontor, Østre Nesttunvei 18 Leietaker er ansvarlig for at dører holdes lås under arrangement eller at det er vakt i døren',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
