INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'45',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='12'),'Storsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,'Kultursal Storsal m/mobilt amfi og scene Amfiet har 146 sitteplasser I tillegg kan det plasseres ca 40 stoler på flatt gulv Scenen er modulær, og kan bli mellom 2 og 24 m2 Når amfiet er inne kan salen romme ca 100 v/langbord 115 stoler Storskjerm og prosjektor Taleanlegg med to trådløse mikrofoner Kultursalen har også komplett lyd- og lysrigg. For å benytte disse må man ha prfesjonell lys og lydtekniker. Kulturkontoret kan formidle kontakt med teknikere. Hverdager: Arrangementet må være avsluttet senest kl. 2300 Røykmaskin er ikke tillatt. Prakisk informasjon ved utleie av kultursalen Kulturlokalene er først og fremst beregnet til kulturaktiviteter men leies også ut til konferanser, seminarer, møter etc. (leies ikke ut til private formål) Renhold utføres en gang pr. dag, mandag tom fredag. Opprydding, leietaker er ansvarlig for opprydding etter arrangement. Leiepriser: kr. 1000,- inntil 4 timer kr. 3000,.- for hele dagen kr. 5000,- helg (kr. 2500,- pr. dag) Frivillige lag/organisasjoner kan ha rett på gratis lån av kultursalen.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
