INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'745',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Klubben',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Klubben er et fleksibelt rom på ca. 84 m2 som passer for mange ulike aktiviteter. Det er greit med plass til ca. 40 personer og lokalet egner seg spesielt godt som klubblokale og møte- og kurslokale. Ved større arrangementer kan Klubben brukes som støtteareal for Kultursal og Multisal. Klubben har inngang ved Servicesenteret, men det er også anledning til å benytte en egen separat inngang fra hentepunkt direkte utenfor. Videre er det dør inn fra biblioteket for arrangementer i samarbeid med Bergen offentlige bibliotek. Klubben har fastmontert projektor med automatisk lerret, samt et enkelt lydanlegg uten mikrofon. Ved behov for større lyd-/lysanlegg og tekniske tjenester, må dette avtales direkte med teknisk ansvarlig Sveinung Myrjord, e-post: sveinung.myrjord@bergen.kommune.no Lokalet har et lite kjøkken med kaffetrakter, komfyr, kjøleskap og oppvaskmaskin - og en lang kjøkkenbenk langs veggen. Der er 33 stoler og 14 bord. Leietaker har selv ansvar for å vaske og rydde på plass utstyr som er brukt. Inventaret i lokalet må settes på plass som anvist på oppslag etter arrangementet, viss det er flyttet på.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
