INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'386',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='98'),'Dans/Musikk 1 og 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='36'),NULL,NULL,'Dans/musikk 1 og 2 er et stort rom som kan deles med skillevegg. Rommet blir mye brukt av ulike dansegrupper og til dansekurs. Rommet leies normalt ikke ut til privatarrangement, med unntak av barneselskaper (opp til 15 år). Begge delene av rommet har speil. Totalt er rommet ca 110 kvm Dans/musikk 1: 45 kvm Dans/musikk 2: 65 kvm For leievilkår, prisliste, etc, se "Ny-Krohnborg senter" (bygg/anlegg).',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
