INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'743',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='153'),'Multisal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,'Multisal er beregnet for konserter, forestillinger, seminarer og samlinger, og kan også brukes som støttelokale for storsalen ved spesielt store arrangementer. På tider det ikke er publikumsrettede arrangementer kan den benyttes for øving for større musikkgrupper, dans og musikkteater. Scenestørrelse: Ca. 60 m2. Kapasitet når heve og senke-speilet er oppkjørt: 126 sittende i rulleamfi, eventuelt 250 stående på flatt golv - pluss eventuelt medvirkende på scenen. Kapasitet når heve og senke-speilet er nedkjørt: Totalt 30 personer i i lokalet. Dette er en moderne sal med god justerbar akustikk (EAS) og profesjonelt utstyr. Det er stor sceneinngang hvor utstyr kan tas inn direkte på scenen. Garderobe 1 og Garderobe 2 ligger i umiddelbar nærhet og kan leies sammen med salen, og et felles backstage-område kan benyttes. Krav til bruk av teknisk utstyr i Multisal: • For å bruke salens utstyr stilles det krav til at arrangør har med erfarne lyd-, lys- og sceneteknikere/systemteknikere. Alternativt kan kulturkontoret være behjelpelig med å skaffe teknikere via våre kontakter - kontakt teknisk ansvarlig Sveinung Myrjord, e-post: sveinung.myrjord@bergen.kommune.no • Det skal ikke gjøres endringer i teknisk oppsett uten at det er avtalt med husets systemtekniker.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
