INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'927',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='171'),'Skolekjøkken',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='5'),NULL,NULL,'Skolekjøkenet er blant annet utstyrt med: Langbord med 16 sitteplasser 5 arbeidsstasjoner med stekeovn, kokeplater, vask og oppvaskmaskin Stor kaffekoker Vannkoker Mikrobølgeovn Kjøleskap med fryser Flere vaffeljern 5 miksmastere og flere stavmiksere 2 ekstra store kjeler Service, bestikk og serveringsfat Ca 50 vinglass Vaskemaskin og tørketrommel Strykebrett og strykejern Tilhørende møterom med 8 sitteplasser og skjerm Mulighet for å henge fra seg yttertøy Førstehjelpsutstyr i3touch skjerm - i3TOUCH er ein stor, interaktiv skjerm som fungerer som ei digital tavle. Du kan skrive, teikne og styre innhald direkte på skjermen med fingeren eller ein penn Innebygde høgtalarar, USB-C-tilkopling Fult utstyrt skolekjøkken. Utstyret kan brukes, men skal være vasket og lagt tilbake på plass før man forlater rommet. Størrelse: 95m ² + 21m2','Ukedager: 08.00-21.00 Lørdag og søndag: 10.00-17.00 Weekdays: 08.00-21.00 Saturday and Sunday: 10.00-17.00 Dersom du ønsker å leie eller låne lokaler utenom ordinær åpningstid, er det krav om å bestille og betale for vektertjenester. Vekter må være til stede under hele leieperioden, og kostnaden for dette er 700 kroner per time. If you wish to rent or borrow the premises outside regular opening hours, it is required to book and pay for security services. A security guard must be present throughout the entire rental period, and the cost for this is 700 NOK per hour.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
