INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'734',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='158'),'Kanoer (6 stk) m/tilhenger',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='14'),NULL,NULL,'Etat for idrett har 6 kanoer og medfølgende årer og vester til utlån for skoleklasser, lag, organisasjoner med flere. Ønsker du å låne kanoene sender du søknad via Aktiv kommune til Etat for idrett (kalender nedenfor). Lån av kanoene er gratis. Søknad kan bli avslått dersom utlån/innleveringstidspunkt faller utenfor Etat for idrett sine åpningstider mandag til fredag kl. 08.00 - 15.00. Regler for bruk av kano/kajakk: Bruk av redningsvest/flytevest er påbudt. Personer som ikke er svømmedyktige må bruke redningsvest. Låntaker er ansvarlig for bruk av kanoene/kajakkene og skal alltid ha oppsyn med bruken. Ansvarlig må være fylt 18 år og kunne grunnleggende førstehjelp. Kanoene/kajakkene tømmes for vann etter bruk. Vestene tørkes før innlevering. Mangler ved lånt utstyr skal innrapporteres. Kanoer Vi har til utlån 6 kanoer av typen Hasle. Kanoen har plass til 3 personer V ektkategorier flytevester: 30-40 kg . 40-50 kg 50-60 kg 60-70 kg 70-90 kg 90 kg +','Utlevering mandag til fredag kl. 08.00 - 15.00.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'637',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='158'),'Kanoer i Nipedalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='14'),NULL,NULL,'Etat for idrett har 8 kanoer og 4 kajakker til utlån for skoleklasser, lag og organisasjoner. Ønsker du å låne kanoene og/eller kajakkene sender du søknad via Aktiv kommune til Etat for idrett (kalender nedenfor). Lån av kanoene/kajakkene er gratis. Nøkkelen ligger i en nøkkelboks som henger på kanonøstet. Kode til nøkkelboksen blir sendt ut når søknaden er innvilget. Nøkkelen må legges tilbake på plass etter bruk. Dersom vi ikke får tilbake nøkkelen vil vi fakturere ansvarlig låntaker 500,-. Arrangementet må ha en ansvarlig person som er over 18 år. Vedkommende må ha kunnskap om førstehjelp og ha mobiltelefon tilgjengelig dersom uhellet er ute. Regler for bruk av kano/kajakk: Bruk av redningsvest/flytevest er påbudt. Personer som ikke er svømmedyktige må bruke redningsvest. Låntaker er ansvarlig for bruk av kanoene/kajakkene og skal alltid ha oppsyn med bruken. Ansvarlig må være fylt 18 år og kunne grunnleggende førstehjelp. Kanoene/kajakkene tømmes for vann og låses på plass i kanonøstet etter bruk. Vester og årer ryddes på plass i boden. Mangler ved lånt utstyr skal innrapporteres. Kanoer/kajakker er oppbevart i et naust på stranden ved Tennebekktjørna øverst i Nipedalen. Årer og vester er lagret i boden på enden av naustet. Nøkkelen skal legges tilbake i nøkkelboksen etter bruk. Kanoer, kajakker og utstyr: Kano merke/modell: Pelican 15,5 Ant. Personer 3 (evt. 2 voksne og 2 barn), lengde 472 cm, bredde 94 cm, vekt 34 kg. Kajakk merke/modell: Pelican Argo Lengde 305 cm, bredde 71 cm, vekt 16 kg. Av utstyr hører det med stk padleårer, redningsvester og flytevester. Vester og padleårer er lagret i boden i nøstet. Her kan man også låse inn sekker eller annet nødvendig mens kanoene er i bruk. Vi har flytevester i følgende vektkategorier: 30-40 kg - 10 stk 40-50 kg - 6 stk 50-60 kg - 5 stk 60-70 kg - 5 stk 70-90 kg - 4 stk 90 kg + - 4 stk Vi har redningsvester i følgende vektkategorier: 10 -25 kg - 3 stk 20 - 35 kg -3 stk',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'979',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:bergen' AND b.ekstern_id='187'),'OUTOOK TEST Spelhaugen 22 Testrom - Holbergstuen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:bergen' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Outlook testrom',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4601' AND fi.kildenokkel='aktiv-kommune:bergen' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
