INSERT INTO bygning (kommune_id,navn,bydel_navn,fagsystem_instans_id,ekstern_id,hjemmeside,epost,telefon,apningstid_tekst) SELECT k.id,'Hundvåg Bydelshus - Øyahuset','Hundvåg',fi.id,'103','https://site1.aktiv-kommune.no/1103/bookingfrontend/?menuaction=bookingfrontend.uibuilding.show&id=103&click_history=9fda9b0dd379e4f85491c8370fd10786','oyahuset@stavanger.kommune.no','47472361','Vanlige uker: Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset Husk å kontakte lederen ved bydelshuset for å avtale et møte. Åpningstidene er veiledende, og det kan forekomme perioder hvor det ikke er ansatte til stede på bydelshuset. Dette skyldes at vi også har arbeidsoppgaver og ansvar utenfor huset. I forbindelse med avspasering, ferieavvikling og annen aktivitet kan det være at vi ikke er tilgjengelige enkelte dager, selv om bydelshuset normalt holder åpent. Vi anbefaler derfor å ta kontakt på forhånd for å sikre at noen er til stede når du kommer. Perioder der bydelshuset er stengt i 2026: Julestengt: 24. Desember - 3. Januar 2027' FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT DO NOTHING;
