INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'338',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='110'),'Landskapet arbeidsplass 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='37'),NULL,NULL,'KONTORFELLESSKAP - 1 arbeidsplass Romstørrelse: 20 m² Lån en arbeidsplass. Det totalt seks plasser i kontorfellesskapet. Arbeids plasser kan lånes i inntil to uker sammenhengende eller inntil 20 dager over en tre måneds periode. Det er også mulig å droppe innom og låne en arbeidsplass på dagen dersom det er tilgjengelige plasser. Vi håper at arbeidsfellesskapet kan bidra til fellesskap, deling av kompetanse og ideer og videre samarbeid . FASILITETER: WIFI - Sikkert høyhastighet trådløst bredbånd, kommunalt nettverk og gratis publikumsnett. Fleksible PC skjermer, hev- og senkbare skrivebord og låsbare skap for oppbevaring DIGITALT UTSTYR - PC-skjerm, Buet UltraWide LCD-Skjerm','Møterom og drop-in arbeidsplasser: Mandag - fredag kl. 8 – 22. (møtet må være avsluttet og lokalene ferdig ryddet til kl. 22) Innbyggertorget er bemannet: mandag - fredag kl. 08.30 – 15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
