INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'502',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='137'),'Igloen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='61'),NULL,NULL,'Igloen er et overbygget samlingssted på Hillevåg torg med sitteplasser og plass til aktiviteter. Igloen er en del av den midlertidige møbleringen på Hillevåg torg og er utviklet i samarbeid med Hillevåg-satsingen, lokale elever, kunstner Kjetil Dybvik og Tjensvoll KFUK-KFUM-speiderne. Hvem kan booke? Frivillige lag, foreninger og skoleklasser kan låne Igloen gratis, eksempelvis til møter eller avslutninger. Den kan også lånes ut for faste aktiviteter organisert av lag og organisasjoner eller frivillige. Rydding står man selv for. Kapasitet Igloen er møblert med et femkantet bord, 5 benker, ekstra plass til rullestol og har kapasitet til 8-12 personer. Bookingtider · Mandag-lørdag: kl. 10.00-21.00 · Søndag: kl. 10.00-21.00 Tilgang Igloen skal være låst når den ikke er i bruk mandag - lørdag etter klokken 18:00, og hele søndagen. Nøkkel kan da hentes og leveres i nøkkelboksen. Nøkkelboksen er plassert på bokboden i nærheten. Du får koden til nøkkelboksen sammen med bekreftelsen på bookingen. Det er ikke tillatt med inntak av alkohol i Igloen.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
