INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'312',k.id,NULL,'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'Storsalen i Sunde/Kvernevik bydelshus er godkjent av brannvesenet for 170 personer sittende, med bord og stoler, og for 240 personer stående uten bord og stoler. Bydelshuset har lydannlegg og to mikrofoner. Cd-spiller etc. må den enkelte ta med selv samt tilhørende ledninger Salen kan brukes til alle type arrangementer. Ønsker du å leie med kjøkkenfasiliteter må du søke om hele bydelshuset eller du kan eventuellt skrive i kommentarfeltet at du ønsker tilgang til kjøkken i sambruk med andre brukere., Bydelshuset har trådløst internett, men har per dags dato ikke projektor. Nøkler hentes samme uke som arrangementet skal foregå på følgende dager: Tirsdag. 18.00-21.00 Torsdag: 13.00-15.30 Det gjøres oppmerksom på at det ikke er tillatt å nyte alkohol.','Fritidsleder Atle H. Wold Tlf: 51508663 / Mob:95225934 Fritidsleder Martin T. Rinde Tlf: 51508666',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
