INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'126',k.id,NULL,'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Gymsalen er 24x12 meter. Det er to garderober knyttet til gymsalen. Tilgjengelig utstyr i gymsalene varier. Det er feste til volleyballstenger, innebandy og to basketballkurver på 2,4 meter. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal mandag-fredag kl.17.00-20.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
