INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'251',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='88'),'Møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Møterommet er utstyr med bord, stoler, TV-skjerm og et mindre kjøkken med kiosk. Møterommet og kjøkkenet kan avgrenses med skillevegg.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'322',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='107'),'Ungdomslokale/Grevlingen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='30'),NULL,NULL,'Ungdomslokalet/Grevlingen består av et oppholdsrom, kjøkken og diskotek. Det er plass til ca 40 personer. Lokalet leies ut til barnebursdager, konfirmasjoner, og andre arrangement. Lokalet leies ut til barnebursdager alle kvelder unntatt tirsdag og torsdag. Lokalet kan benyttes fra kl. 16.30. Nøkkelutlevering forgår på følgende dager: Tirsdager mellom Kl. 16.00 - 17.30 Brannsikkerhet, renholdsrutiner og innbruddsalarm blir gjennomgått ved nøkkelhenting .',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'148',k.id,NULL,'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Roaldsøy skolegymsal er på 16m x 12m. Det er to garderober som benyttes både til gymsal og basseng. Tilgjengelig utstyr i gymsalene varier. Det er stenger og nett til volleyball, innebandymål, diverse matter og 2 basketballkurver. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal og basseng mandag-torsdag kl.17.00-20.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'163',k.id,NULL,'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Vardenes skolegymsal er på 19m x 9m. Det er to garderober, som også er tilknyttet bassenget. Tilgjengelig utstyr i gymsalene varier. Det er 2 basketballkurver på 2,05 meter. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal mandag-torsdag kl.17.00-22.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'323',k.id,NULL,'Fritidssenteret',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,'Fritidssenteret leies kun ut til barnebursdager, skoler barnehager og SFO. Øvrig utleie foregår på Sunde/kvernevik bydelshus . Maksimumstiden for leie er 4 timer ink. forberedelser i forkant og etterkant. Leie av senteret til barnebursdag koster kr.500. Vi leverer ikke Dj tjenester lenger. Men det er mulighet for å spille selv ved å koble seg opp til smartphone, ipad eller pc og bruke f.eks spotify, Det finnes egen nøkkel til å skur på lyd og lys. Skoler, SFO og barnehager får tilgang gratis. Lokalet leies ut til barnebursdager mandager, onsdager, lørdager og søndager samt fredager i oddetallsuker. Dette vil fremkomme i kalenderoversikten For aldersgruppen 15-18 må en særskilt kontrakt underskrives av foresatte samt at det gjennomføres en samtale med fritidsleder i forkant. Nøkkelutlevering forgår på følgende dager: Tirsdager mellom kl. 18.00 & 20:00 Torsdager mellom kl. 13.00-16.30 Dette gjelder også de som skal ha selskap påfølgende uke mandager eller onsdager. Brannsikkerhet, renholds-rutiner og innbruddsalarm blir gjennomgått ved nøkkelhenting.','Fritidssenteret leies ut følgende dager: Mandager: 16.00-21.00 Onsdager: 16.00-21.00 Fredager i oddetallsuker: 16.00-21.00 lørdager: Hele dagen (maks 4 timer per selskap) Søndager: Hele dagen (maks 4 timer per selskap)',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'165',k.id,NULL,'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Vassøy skolegymsal er på 19m x 7,5m. Det er to garderober. Tilgjengelig utstyr i gymsalene varier. Det er feste og nett til volleyball og 2 basketkurver på 2 meter. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal mandag-torsdag kl.17.00-20.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'129',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='45'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Gausel skolegymsal er 20x10 meter. Gymsalen har to garderober. Tilgjengelig utstyr i gymsalene varier. Det er to basketballkurver, 2 tjukkaser, bom, ribbevegger, tauer og benker. Har også eget rom til oppbevaring av lånetakers utstyr. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal og basseng mandag-torsdag kl.17.00-22.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'169',k.id,NULL,'Basseng',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='14'),NULL,NULL,'Kannik skolebasseng er på 25m x 10m. Dybde 0.90 - 2,50m. Der er to garderober til bassenget. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut basseng mandag-fredag kl.17.00-22.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'138',k.id,NULL,'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Kampen skolegymsal er på 20m x 8,5m. Det er to garderober. Tilgjengelig utstyr i gymsalene varier. Det er stenger og nett til volleyball, 2 basketballkurver, innebandymål og en liten klatrevegg. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal mandag-torsdag kl.17.00-20.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'124',k.id,NULL,'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Gymsalen er 18x9 meter. Det er to garderober knyttet til gymsalen. Tilgjengelig utstyr i gymsalene varier. Det er stenger og nett til volleyball, og 2 basketballkurver. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal og basseng mandag-torsdag kl.17.00-22.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'130',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='46'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='6'),NULL,NULL,'Godeset skolegymsal er 20x10 meter. Det er to garderober. Tilgjengelig utstyr i gymsalene varier. Det er stenger og nett til volleyball, innebandymål og 2 basketballkurver. Har også ca. 10 matter, to tjukkaser, spingbrett, bukk og ringer i taket. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal og basseng mandag-torsdag kl.17.00-20.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'393',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='124'),'Bordtennis',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'414',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='129'),'Møterom Kjellerverkstedet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Møterommet er plassert i underetasjen på Sølvberget bibliotek og kulturhus. Møterommet har klasseromsoppsett med 10 bord og 20 stoler og har plass til 5-20 personer. Vennligst book ett av våre mindre grupperom for grupper på 2-4 personer.','16-21',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'334',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='109'),'Store møterom /Kafè',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'OBS! I helgene kan man vanligvis ikke leie kun cafeen. Man leier vanligvis hele første etg, og da er store møterom/cafeen del av dette.. Hvis huset er utleid til noen som kun skal bruke storsal kan du få leie store møterom/cafeen, men da er de to parallelle leietagerne klar over hverandre og kommuniserer. Du kan da enten leie rommet for hele dagen eller starte tidlig og ha etasjen frem til kl 16.00 eller starte kl 16.00 og ha etasjen frem til kl 23.45. Store møterom er 46 kvm og ligger vegg i vegg med kjøkkenet.(det er en luke i mellom disse som kan stenges om ønskelig).',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'331',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='109'),'Glassburet /lille møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'I helgene følger dette rommet med i utleien av hele etasjen og leies vanligvis IKKE ut alene. Unntak kan gjøres, men da må dere kontakte oss og avtale dette spesielt. Glassburet/lille møterom er et trivelig rom på ca 23 kvm med sofaer og stoler. Det er også husets bibliotek, og brukes til små uformelle møter og til avslapning, amming etc. Rommet passer for opp til 12-20 stk.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'307',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='104'),'Kafé/ Kjøkken',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='28'),NULL,NULL,'Kafé/Kjøkken på Madla bydelshus består av kjøkken og kafé med sitteplasser til ca. 50 personer. Kjøkkenet er et ordinært brukskjøkken med komfyr, kjøleskap og steamer, men egner seg ikke til matproduksjon i storformat. Kjøkkenet er mest egnet for tilrettelegging av allerede tilberedt mat. Rommet kan brukes til møter, mindre samlinger, kurs, dåp, konfirmasjon etc. Man må regne med at man til tider må dele kjøkken med andre brukere på huset. Brannsikkerhet, renholdsrutiner og innbruddsalarm blir gjennomgått ved nøkkelutleveringen. Det gjøres oppmerksom på at det ikke er tillatt å nyte eller være påvirket av alkohol på de kommunale bydelshusene. Dette i henhold til vedtak i kommunalstyret for oppvekst og levekår.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'34',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='24'),'Kunstgressbane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Banen har en spilleflate på 95 x 48 meter. Avhengig av årstiden har anlegget belysning (200 lux) mandag-fredag og søndag innenfor tidsrommet 16:00 - 22:15.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
