INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'370',k.id,NULL,'Sletteberget',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Sletteberget er en del av Ørneberget som kan deles i to rom med skillevegg slik at man får to grupperom. Slettberget vil kunne romme opp til 20 personer . Vi tilbyr også catering tjenester til selskaper, møter og konferanser. For bestilling eller forespørsel kan man ta kontakt på følgende tlf. 40188381 eller E-post: drifa.jaatit@gmail.com Tilbudet drives av sosialt nettverk som er en frivillig organisasjon i bydelen hvor pengene de tjener går tilbake til lokalsamfunnet bla. integreringstiltak i nærmiljøet',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'376',k.id,NULL,'Kafèkjøkken',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Vi tilbyr catering tjenester til selskaper, møter og konferanser. For bestilling eller forespørsel kan man ta kontakt på følgende tlf. 40188381 eller E-post: drifa.jaatit@gmail.com Storkjøkken er tilknyttet kafe og kan leies/brukes til produksjon av mat til store og små selskaper etc. Man kan også kan kombinere å leie storkjøkken i.f.b med bruk av andre rom i huset eller kafèområdet hvor det skal serveres mat. Kjøkkenet er godt utstyrt med dampkoker, induksjonsovn, steamer og god fryse og kjøleskap kapasitet.','Etter avtale',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
