INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'373',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='122'),'Ørnaberget/Sletteberget',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Ørnaberget er vårt største møte/konferanserom som tar opp til 50 personer når det er åpent men også kan deles i to hvor det da blir to lokaler henholdsvis Sletterbeget og Ørneberget. Dette lokalet egner seg godt til alt fra konfirmasjon, dåp og bryllup til Kulturaktiviteter og kurs konferanser i middels store grupper.','Etter avtale',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'377',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='122'),'Kjøkken 2 etg.',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Storkjøkken med direkte tilknytting til Rygja og kafe område med plass til 25 personer.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'306',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='104'),'Grupperom 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Per dags dato har vi ett grupperom til leie. Dette passer bra til små hobbygrupper, møter, leksegruppe, etc. Nøkkelutlevering avklares nærmere på telefon eller mail ved tildeling av rom. Brannsikkerhet, renholdsrutiner og innbruddsalarm blir gjennomgått ved nøkkelutleveringen. Det gjøres oppmerksom på at det ikke er tillatt å nyte eller være påvirket av alkohol på de kommunale bydelshusene. Dette i henhold til vedtak i Utvalg for oppvekst og utdanning.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'406',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='128'),'Hverdagsscenen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='52'),NULL,NULL,'Informasjon om standplassen: Størrelse på plassen er 2x2 meter. Det er ikke anledning til å sette opp telt. Det er tilgang til strøm fram kumme ved benk',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'419',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='130'),'Garderobe 4',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='59'),NULL,NULL,'Alle rommene har HC tilrettelagt toalett og dusj. Felles åpent internett på hele bygget «DNB-Arena» Ingen garderober har skap, men alle sitteplassene har overhyller til oppheng av ishockeyutstyr, samt kurv under benken.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'420',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='130'),'Garderobe 5',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='59'),NULL,NULL,'Alle rommene har HC tilrettelagt toalett og dusj. Felles åpent internett på hele bygget «DNB-Arena» Ingen garderober har skap, men alle sitteplassene har overhyller til oppheng av ishockeyutstyr, samt kurv under benken.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'300',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'Storsalen på Øyahuset kan dekkes med inntil 150 personer. Salen kan brukes til alle type arrangementer. Ønsker du å leie med kjøkkenfasiliteter må du søke om hele bydelshuset eller du kan eventuelt skrive i kommentarfeltet at du ønsker tilgang til kjøkken i sambruk med andre brukere. Rommet disponeres i tillegg med: mikrofon, liten scenen, høyttalere, projektor, lerret, stort speil på 1 av veggene, diskolys til barnebursdag, teleslynge for nedsatt hørsel. PC, Cd spiller etc. må den enkelte ta med selv, samt tilhørende ledninger. Bydelshuset har annen mikrofon for utlån etter avtale. Bydelshuset har trådløs internettforbindelse. Det gjøres oppmerksom på at det ikke er tillatt å nyte alkohol på de kommunale bydelshus. Dette i henhold til vedtak i kommunalstyret for oppvekst og levekår.','Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'403',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='127'),'Møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='49'),NULL,NULL,'Det er 6 bord og 20 stoler i lokalet, samt mulighet til å bruke Naturvernforbundet sine ekstra klappstoler Det er en enkel projektor med HDMI-utak og trådløst internett(SK-Public) Kjøkkenet er lite og egner seg best som klargjøringskjøkken. På kjøkkenet er det kaffemaskin til filterkaffe. Alle reservasjoner må godkjennes. Nøkkelkode sendes ut til leietaker 15 minutter før bookingen starter.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'359',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='111'),'Nordic Edge Stand',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='42'),NULL,NULL,'Aktiv kommune er en portal til aktiviteter og ressurser. La kommunens ressurser; som for eksempel lokaler, anlegg, uteområder og utstyr komme enda flere innbyggere, lag og organisasjoner til gode gjennom utleie/utlån. Gjør de kommunale ressursene lettere tilgjengelig gjennom den digitale løsningen Aktiv kommune. Aktiv kommune er en digital tjeneste for leie og utlån av kommunens lokaler, anlegg, uteområder og utstyr. Kommunene får en digital saksbehandling og en plattform som kan brukes på tvers av avdelinger, og innbyggerne får en enkel selvbetjeningsportal.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'411',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='129'),'Møterom Utsikten',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Møterommet er plassert i 4. etasje på Sølvberget bibliotek og kulturhus. Møterommet har plass til grupper med 5 og opptil 12 personer. Vennligst book et av våre mindre grupperom for grupper på 2 - 4 personer','16-21',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'413',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='129'),'Arrangementsrom Klasserommet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='56'),NULL,NULL,'Arrangementslokalet Klasserommet er plassert i 3. etasje på Sølvberget biblitek og kulturhus. Lokalet kan brukes til arrangement, møter, kurs, seminarer og konferanser. Rommet har plass til 60 personer i klasseromsoppsett. (egne vilkår gjelder) Rommet leies ikke ut som selskapslokale, eller til private sammenkomster.','16-21',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'400',k.id,NULL,'Møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Hovedrommet har plass til 40 personer. I siderommet er det plass til 8 personer. Projektor med HDMI kobling i begge rom Høyttaler i hovedrom Tekjøkken med tilgang til vann. Kaffe medbringes, kaffetrakter og komfyr er ikke tilgjengelig for bruk. Skolen er en rusfri arena og rusmidler skal selvsagt ikke benyttes NB! Ingen nøkler gis ut. Kode til dør sendes ut på SMS 15 minutter før din booking starter.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'394',k.id,NULL,'Kafè',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='28'),NULL,NULL,'Bydelshusets kafè er hjertet i huset hvor folk kan møtes over en kopp kaffe eller spise en bedre middag til en billig penge. Kafeen er utstyrt med et hypermoderne storkjøkken som kan brukes til storproduksjon av mat i.f.b med store arr. i våre store festsal Rygja. Vi tilbyr også catering tjenester til selskaper, møter og konferanser. For bestilling eller forespørsel kan man ta kontakt på følgende tlf. 40188381 eller E-post: drifa.jaatit@gmail.com Tilbudet drives av sosialt nettverk som er en frivillig organisasjon i bydelen hvor pengene de tjener går tilbake til lokalsamfunnet bla. integreringstiltak i nærmiljøet','09.00-13.00 mandag-fredag',TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'310',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='104'),'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'I storsalen på Madla bydelshus er det anslagsvis plass til 150-200 personer. Storsalen har høyttaleranlegg og en mikrofon. Salen kan brukes til de fleste typer arrangementer. Eget lager for stoler og bord som kan settes ut selv ved behov. Nøkkelutlevering avklares nærmere på telefon eller på mail ved tildeling av rom. Brannsikkerhet, renholdsrutiner og innbruddsalarm blir gjennomgått ved nøkkelutleveringen. Det gjøres oppmerksom på at det ikke er tillatt å nyte eller være påvirket av alkohol på de kommunale bydelshusene. Dette i henhold til vedtak i kommunalstyret for oppvekst og levekår.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'272',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='95'),'Kjøkken / Kafè',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Med plass til ca 50 personer, kjøkken, kafeområde og vinterhagen er perfekt til barneselskap og klassefester men passer også til små familiefest og sosiale arrangementer. Kjøkkenet er et ordinært brukskjøkken med komfyr, kjøleskap og egner seg ikke til matproduksjon i storformat. Kjøkkenet er mest egnet for tilrettelegging av allerede tilberedt mat. Tidspunktet du bestiller inkluderer forberedelse og renhold. Du blir kontaktet av fritidsleder når din søknad behandles - du vil få en sms med foreslått tidspunkt for nøkkelhenting på Gausel bydelshus, Heddeveien 141. Sms sendes fra `Stavanger` som avsender. Renholdsrutiner, brannsikkerhet og innbruddsalarm vil bli gjennomgått ved henting av nøkler. Tap av nøkkelkort faktureres i helhet-. Ekstra renhold faktureres i helhet. Kjøkken og kafè kan ikke tildeles til faste brukerne. Ukedager har vi som regel plass til et barneselskap. Lørdager: 12:00 (eller tidligere)-15:00 og 15:00-18:00. 18:00-21:00. Søndag 12:00-15:00, 15:00-18:00 og 18:00-21:00. Slik har vi plass til alle som ønsker å feire hos oss. Man må til tider dele kjøkken med brukere av Storsalen/Lillesalen Gjelder henting av kaffe og kjøkkenutstyr. Ved arrangementer på kjøkkenet skal ikke andre brukere oppholde seg på kjøkkenet/inngangen lengre enn nødvendig. Dette av hensyn til arrangementer som foregår der. English: With room for about 50 people, the kitchen and cafe area are perfect for children''s parties and class parties but are also suitable for small family parties and social events. The kitchen is an ordinary utility kitchen with stove, refrigerator and is not suitable for food production in large format. The kitchen is most suitable for arranging already prepared food. You sometimes have to share a kitchen with users in Lillesal and Storesal. The time you book includes preparation and cleaning. You will be contacted by the center manager when your application is processed - you will receive an SMS with the suggested time for key collection at Gausel community centre, Heddeveien 141. SMS is sent from `Stavanger` as sender. Cleaning routines, fire safety and burglary alarms will be reviewed when collecting keys. In the event of loss of a key card, a surcharge of NOK is added. 500, -. All users must clean up after themselves, otherwise a surcharge of NOK is added. 500, - (per room). Kitchen and café can not be assigned to regular users. On weekdays, we usually have space for a children''s party. Saturdays: 12:00 (or earlier)-15:00 and 15:00-18:00. 18:00-21:00. Sunday 12:00-15:00, 15:00-18:00 and 18:00-21:00. This way we have room for everyone who wants to celebrate with us. At times, you may have to share the kitchen with users of the Storsalen/Lillesalen. This applies to picking up coffee and kitchen equipment. During events in the kitchen, other users should not stay in the kitchen/entrance longer than necessary. This is out of consideration for the events taking place there.','Gausel bydelshus har åpent alle dager! Brukerne får nøkler og er selv ansvarlig for bruk av huset. Det er bare mulig å søke om ledig tid via kalenderen',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'421',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='130'),'Garderobe 6',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='59'),NULL,NULL,'Alle rommene har HC tilrettelagt toalett og dusj. Felles åpent internett på hele bygget «DNB-Arena» Ingen garderober har skap, men alle sitteplassene har overhyller til oppheng av ishockeyutstyr, samt kurv under benken.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
