INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'51',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='32'),'Kunstgressbane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Banen har en spilleflate på 57 x 37 meter. Anlegget har belysning (200 lux) mandag-fredag og søndag innenfor tidsrommet 16:00 - 21:15.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'287',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='96'),'Basseng',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='14'),NULL,NULL,'Svømmebassenget på Finnøy ble bygd i 1971 og rehabilitert i 2014. Bassenget brukes i hovedsak av Finnøy sentralskule og har noe publikumsbading. Finnøy svømmebasseng inneholder et basseng, to garderober med felles badstue og en HC garderobe. Bassenget er 1,5 x 10 meter med en dybde på 0,9 - 1,5 meter. Temperaturen i bassenget er 28 grader. Rullestol til basseng og bassengheis er tilgjengelig på anlegget.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
