INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'346',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='110'),'Samarbeidet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='42'),NULL,NULL,'MØTEDELTAKERE - 6 personer, Romstørrelse: 10 m² Hev og senk bord, med tilhørende hev og senk ergonomisk designet stoler. 1 stor skjerm fastmontert på vegg, med videooppkobling og ClickShare. Stor glassvegg ut mot rommet Landskapet, kontorfellesskap. KODE TIL DØR: Utenfor åpningstid vil du få koden til døren tilsendt på sms 10 min før rommet er booket. FASILITETER: WIFI - Sikkert høyhastighet trådløst bredbånd. kommunalt nettverk og gratis publikums nett. DIGITALT UTSTYR - Et standard møterom med video som er en standard i Stavanger kommune Vegghengt skjerm 75’’ 4K Cisco videokonferansekamera over skjerm. Yamaha lyd på hver side av skjerm. Cyviz styresystem for enkel betjening av rommet. Både trådløs og kablet tilkobling av PC. ClickShare.','Møterom: Mandag - fredag kl. 8 – 22. (møtet må være avsluttet og lokalene ferdig ryddet til kl. 22) Innbyggertorget er bemannet: mandag - fredag kl. 8.30 – 15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'340',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='110'),'Landskapet arbeidsplass 3',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='37'),NULL,NULL,'KONTORFELLESSKAP - 1 arbeidsplass. Romstørrelse: 20 m² Lån en arbeidsplass. Det totalt seks plasser i kontorfellesskapet. Arbeids plasser kan lånes i inntil to uker sammenhengende eller inntil 20 dager over en tre måneds periode. Det er også mulig å droppe innom og låne en arbeidsplass på dagen dersom det er tilgjengelige plasser. Vi håper at arbeidsfellesskapet kan bidra til fellesskap, deling av kompetanse og ideer og videre samarbeid . FASILITETER: WIFI - Sikkert høyhastighet trådløst bredbånd, kommunalt nettverk og gratis publikumsnett. Fleksible PC skjermer, hev- og senkbare skrivebord og låsbare skap for oppbevaring DIGITALT UTSTYR - PC-skjerm, Buet UltraWide LCD-Skjerm','Møterom og drop-in arbeidsplasser: Mandag - fredag kl. 8 – 22. (møtet må være avsluttet og lokalene ferdig ryddet til kl. 22) Innbyggertorget er bemannet: mandag - fredag kl. 08.30 – 15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'97',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='6'),'Møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Hallen har et møterom som kan benyttes seperat eller samlet. Et rom er 20m2. Alle tre rommene samlet er 62m2. .',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'311',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='104'),'Stova',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Stova på Madla bydelshus ligger rett ved kafeen og er et hyggelig rom som egner seg bra for møter, foredrag, foreninger m.m. Det er sitteplass til ca. 25 personer, og møblert med tre sofagrupper, i tillegg til et par bord med stoler. Det er kort avstand til kjøkkenet og er i tillegg rett ved inngangen til Madla bydelshus. Nøkkelutlevering avklares nærmere på telefon eller mail ved tildeling av rom. Brannsikkerhet, renholdsrutiner og innbruddsalarm blir gjennomgått ved nøkkelutleveringen.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
