INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'270',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='95'),'Barnehagerommet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'English below: Barnehagerommet blir disponert av Åpen barnehage mandag, tirsdag onsdag og torsdag på dagtid. Det er mulig å reservere Barnehagerommet til dans, trening, undervisning, små selskap og møter. Dere kan fint organisere en barnebursdag her i ukedagene, da får man 4 timer med valgfrie tidspunkter til 500 kr. Rommet har et kjøkken (kjøleskap/ovn), et spisebord, en sofa og direkte tillgang til lekeplassen. Barna kan spise inne og leke utforbi. Lekene/utstyr følger ikke med - disse er eid av Bamsefaret Åpen Barnehage og leies ikke ut. Flere stoler/bord kan fraktes fra andre rom om nødvendig (må leveres tilbake). Tidspunktet du bestiller inkluderer forberedelse og renhold. English: The kindergarten room is used by Open Kindergarten on Monday, Tuesday, Wednesday and Thursday during the day. In the afternoons it is possible to book the Kindergarten Room for dancing, training, teaching, small parties and meetings. You can organise birthdays here, the children will then eat inside and go play diretly outside on the playground. The room has an oven and a small fridge, a dining table, a sofa and direct access to the playground. In the weekdays you can book 4 hours here for birthday parties. More chairs and tables may be borrowed from other rooms, please remember to take them back. The time you book includes preparation and cleaning. The toys/mats are not for rent - it is Bamsefaret Åpen Barnehage that owns these and we do not rent them out.','Gausel bydelshus er alltid åpen! Brukerne får nøkkelen og tar ansvar for huset. Barnehagerommet er åpent for leie hver dag: NB! det er kun mulig å søke om ledig tid via kalenderen.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'429',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='111'),'Sal A',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='42'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'94',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='5'),'Møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Møterommet er ca 60 m2',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'444',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='133'),'Møteplassen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='49'),NULL,NULL,'Møteplassen ligger inne i Pølsesvingen. Dette er et m øterom med plass til 4 personer, med to lenestoler, en liten sofa, skjerm. Det er mulighet for å lage kaffe og te og bruke kjøleskapet på det nærliggende kjøkkenet. Praktisk info: Utenfor åpningstid vil du få koden til døren tilsendt på sms 10 minutter før rommet er booket. Husk å legge inn nok tid til å rigge før og rydde etter bruk. Rommet skal se like fint ut når du forlater det som da du kom.','Mandag - søndag kl. 08:00 - 23:00. Dørene er åpne og ansatte er på lokalet mandag til fredag kl. 9 - 15. Utenom disse tidene brukes tilsendt kode på sms ved booking.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
