INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'457',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='134'),'Plass 11',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='52'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'463',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='135'),'Barneskole, ekskursjon',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='49'),NULL,NULL,'Klassene ønskes velkommen fra kl 0900. Først blir program for dagen og sikkerhetsrutiner gjennomgått. Lundsvågen naturskole har redningsvester til alle som kommer på besøk. Deretter går turen ut på sjøen for å dra garn, ruser og teiner. Vel tilbake på bryggene får alle elevene hjelpe til med å ta fisk og krabber ut av teiner og garn. Krabbene kokes og fisken tilberedes for grilling. Avskjæret (hoder og rygg) brukes til agn i teinene til neste dag. Når fiskeredskapene er renset og klare for å bli satte ut igjen, er det tid for matpakken (ca 1030). Denne spises utendørs samtidig som en av lærene underviser om fangsten vi har fått. Kanskje lærer vi noen nye fiskenavn? Som siste del av undervisningen går klassen inn i saltvannsakvariet som skolen har. Her får vi se en mengde fisker og dyr som finnes i havet utenfor Hundvåg. Etter teoritimen går turen til Langøy (ca 1130). Her kan elevene grille, ro i robåter, padle i kanoer/kajakk, ro i raftingbåt og fiske småfisk med stintesnører som vi har. Avreise fra Langøy ca 1330 Avreise fra Lundsvågen kl 1400 Huskeliste for besøkende lærere og elever: Ankomst: Ta buss nr. 1A/1B fra Stavanger sentrum-Klubbgata ca kl 0830. Gå av ved Lunde skole/KIWI. Følg skiltene på den 10 min lange spaserturen til Lundsvågen naturskole. Avreise: Kl 1400. Gå til Lunde skole der buss nr. 1A/1B passerer. (Buss nr. 38 går fra Lundsvågen naturskole kl 1400, med bytte til buss nr.1 v/Kiwibutikken Mat: Alle elever tar med både matpakke (brødskiver/kjeks) og grillmat + drikke Klær: Regnklær, støvler, lue, vanter, ullsokker + ekstra sokker. Vi skal være ute hele dagen uansett vær, og været skifter ofte i løpet av en dag. Uansett er det mye kaldere på sjøen enn på land!',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'445',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='133'),'Spikeren',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Spikeren – Møterom Beskrivelse: Møterom med plass til 12 personer. Rommet et utstyrt med to lange møtebord og 12 stoler, og en whiteboard på veggen. Det finnes også en mobil skjerm på hjul tilgjengelig for presentasjoner eller videomøter. Praktisk info: Utenfor åpningstid vil du få koden til døren tilsendt på sms 10 minutter før rommet er booket. Husk å legge inn nok tid til å rigge før og rydde etter bruk. Lokalet skal se like fint ut når du forlater det som da du kom.','Åpningstider Mandag - søndag kl. 08.00 - 23.00. Dørene er åpne og ansatte er på lokalet mandag til fredag kl. 9 - 15. Utenom disse tidene brukes tilsendt kode på sms ved booking.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'345',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='111'),'Idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='42'),NULL,NULL,'Aktiv kommune er en portal til aktiviteter og ressurser. La kommunens ressurser; som for eksempel','Åpningstider Mandag-Fredag: 10:00-16:00 Lørdag: 10:00-15:00 Søndag: Stengt',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'443',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='133'),'Pølsesvingen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Pølsesvingen- åpent møte/samlingsområde med te-kjøkken Stort og fleksibelt område i fellesarealet med plass til opptil 30 personer, og har cirka 122 m2. Te-kjøkken med kjøleskap og utstyr til te og kaffe, en oppvaskmaskin. Møtebord og stoler, lenestoler, sofa. Bord og stoler kan ommøbleres etter ønske. Det finnes også en mobil skjerm på hjul. Tilrettelagt for: Større møter sosiale samlinger kulturlokaler, formidling kulturlokaler, øving og verksteder Kunst, håndverk og media Praktisk info: Utenfor åpningstid vil du få koden til døren tilsendt på sms 10 minutter før rommet er booket. Husk å legge inn nok tid til å rigge før og rydde etter bruk. Lokalet skal se like fint ut når du forlater det som da du kom. Ved behov for mopp eller andre rengjøringsartikler - finner du på vaskerommet ved siden av toalettene',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'325',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='108'),'Storsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'Storsal; 1-25 pers u/møbler avhengig av aktivitet , inntil 50 pers m/møbler; møte, seminar etc.. Lyd- og lysanlegg tilgjengelig ved leie av DJ. Projektor tilgjengelig ved forespørsel. Leies ut til div arrangementer og selskaper, disko ved bursdager og klassefester, seminarer og større møter.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'467',k.id,NULL,'rygja',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'465',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='133'),'Badedammen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='60'),NULL,NULL,'Badedammen (a uditorium)-en romslig sal med scene. Dette er en stor og funksjonell sal på cirka 138 m2, perfekt til ulike arrangementer. Rommet har scene, samtidig mulighet for direktesending av video til en storskjerm. Salen er møblert med 89 komfortable lenestoler og tilrettelagt for rullestolbrukere, slik at alle kan delta på en komfortabel og inkluderende måte. Praktisk info: Utenfor åpningstid vil du få koden til døren tilsendt på sms 10 minutter før rommet er booket. Husk å legge inn nok tid til å rigge før og rydde etter bruk. Lokalet skal se like fint ut når du forlater det som da du kom.','Mandag - lørdag kl. 08.00 - 23.00 Søndag kl. 09.00-23.00 Dørene er åpne og ansatte er på lokalet mandag til fredag kl. 9 - 15. Utenom disse tidene brukes tilsendt kode på sms ved booking.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'332',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='109'),'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'OBS! I helgene bør man leie hele første etg, for vanligvis bruker bare EN gruppe/ett selskap første etg om gangen. Skal du leie til familiefeiring, konfirmasjon, dåp, barnebursdag, større samlinger/arrangementer etc trenger du egentlig hele første etg. Erfaring tilsier at to selskaper samtidig i et såpass lite bygg er mindre heldig. Prisen er uansett den samme. Du kan enten leie hele første etg for hele dagen eller starte tidlig og ha etasjen frem til kl 16.00 eller starte kl 16.00 og ha etasjen frem til kl 23.45. Storsalen på Midjord bydelshus er 105kvm inkludert scene. Salen er godkjent for 85 personer, men hvis alle skal bordsettes er 65 pers. maks. Den egner seg godt til alle typer arrangement, samlinger/konferanser/selskap/feiringer. Når huset leies ut til større arrangement som konfirmasjon, dåp, bryllup, bursdager mm. er sedvanen at hele 1. etasje reserveres til dette. (Storsalen, Store møterom og Kjøkken).',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'333',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='109'),'Kjøkken',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'OBS! Kjøkkenet svært sjelden ut alene. De som leier lokaler til arrangementer i helgene leier hele første etg, og da er kjøkkenet inkludert. Er det flere grupper på huset (mest i hverdagene) må det vises hensyn når man deler på kjøkkenet. Avtal rundt dette på forhånd. I helgene er som sagt kjøkkenet tildelt den gruppen som har leid seg inn i første etg (som oftest kun en gruppe pr etg), men er atelieret utleid samtidig skal også disse ha minimumstilgang for å lage kaffe m.m. Vis hensyn til hverandre er stikkordet. Kjøkkenet er offentlig godkjent og vi har oppvaskmaskin, induksjonskomfyr, microbølgeovn, kjøleskap og de fleste andre nødvendige fasiliteter. Vi har bestikk og service til selskaper inntil 60 personer. Kjøkkenet må vanligvis deles med andre brukere hvis det er flere på huset samtidig. Med unntak av ved større selskaper m.m',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'330',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='109'),'Ateliet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'OBS! Atelieret kan leies selv om det er arrangement i første etg i helgen. Atelieret vårt er et lyst og trivelig rom på 62 kvm som egner seg for alt fra små møter til div hobbyaktiviteter. Passer best for grupper på mellom 10-20 personer. Atelieret ligger i 2.etasje og leies ut uavhengig av hva slags aktivitet 1.etasje er leid ut til, selv under større arrangementer/fester/messer m.m.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'315',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='106'),'Kjøkken',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Der er Kaffetrakter, Takke, Industri komfyr, steamer, mikrobølgeovn, vannkoker, store gryter til husholdning, dekketøy og vannglass, kaffekanner og te kanner, osv. NB! Det er kun mulig å booke ledig tid via kalender. Ved leie av kjøkkenet må man tillate at andre leietakere får koke seg kaffe og hente ut sine saker. Nøkler skal hentes på Bekkefaret Bydelshus Tirsdagen før ditt arrangement mellom kl 18 - 19.00. Da skal det være gjennomgang av brannalarm, renhold, alarm. Tiden du har bestilt skal inkludere ordne til og rydde etterpå.','Hver dag er det åpent 8.00 - 23.00 Kontortid: Mandag: 8-15.30 Tirsdag: 10-19 Onsdag: 8-15.30 Torsdag: 10-19 Fredag: 8-15 (partallsuker fri)',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'399',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='125'),'Speiderbasen aktivitetsrom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='57'),NULL,NULL,'Tilrettelagt for: Innendørslokaler, ypperlig som utgangspunkt og samlingsplass ved uteaktiviteter. Det er ikke tillatt med overnatting i bygget. Bygget må gjerne brukes i kombinasjon med overnatting i telt på Speidermarka. SMS med kode kommer 15 minutt før din booking. Plass til 1-30 personer Ved feil meld inn her på denne lenken: Melding (powel.net)','Åpningstider: Alltid åpent',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'320',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='107'),'Kafè',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='28'),NULL,NULL,'Kafeen på Tjensvoll bydelshus består et rom med plass til 30-40 personer. Rommet kan brukes til møter, mindre samlinger kurs, dåp, konfirmasjon etc. Ved møter eller lignende, kan man til tider dele kjøkken med brukere i storsalen. Ønsker man å benytte lokalet uten forstyrrelser bes det om at dette spesifiseres på søknaden. Nøkler hentes samme uke som arrangementet skal foregå og hentes på følgende dager',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'298',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Lille møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Lille møterom har plass til ca. 6-10 personer. Ressurstavlen kan lånes fra Peisestuen. Ligger mellom peisestua og frisøren.','Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'466',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='133'),'Godalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Godalen - mø terom for 4-6 personer. Rommet et utstyrt med et møtebord og 6 stoler. Det finnes også en veggmontert skjerm tilgjengelig for presentasjoner eller videomøter. Praktisk info: Utenfor åpningstid vil du få koden til døren tilsendt på sms 10 minutter før rommet er booket. Husk å legge inn nok tid til å rigge før og rydde etter bruk. Lokalet skal se like fint ut når du forlater det som da du kom.','Mandag - søndag kl. 08.00 - 23.00. Dørene er åpne og ansatte er på lokalet mandag til fredag kl. 9 - 15. Utenom disse tidene brukes tilsendt kode på sms ved booking.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'299',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Peisestuen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Peisestuen er et lite møterom med plass til 15-20 deltagere. Rommet disponeres i tillegg med: TV-skjerm, arbeids tavle, HDMI ledning for TV- og skjermkobling.','Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
