INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'472',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='136'),'Plass 3',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='61'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'317',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='106'),'Møterom 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Møterom 2 har plass til max 6 personer Der er et piano og brukes hver ukedag av en musikkskole. Nøkler skal hentes Tirsdagen før ditt arrangement mellom kl 18 - 19.00 . NB! Det er kun mulig å booke ledig tid via Kalenderen Tidspunktet du bestiller inkluderer forberedelser og renhold(rydding)','Huset er åpent hver dag klokken 8 - 23 (For brukere med nøkkler) Kontortid: Mandag: 8 - 15.30 Tirsdag: 10 - 19 Onsdag: 8 - 15.30 Torsdag: 10 - 19 Fredag: 8 - 15 (i partalluker fri)',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'37',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='27'),'Kunstgressbane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Banen har en spilleflate på 50 x 30 meter, med ekstra kunstgressareal som kan brukes. Avhengig av årstiden har anlegget belysning (200 lux) mandag-fredag og søndag innenfor tidsrommet 16:00 - 22:15.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'474',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='111'),'Outlook',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='42'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'475',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='111'),'test',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='42'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'304',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Fritidsklubben (underetasjen)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='29'),NULL,NULL,'Fritidsklubben kan leies til barnebursdager og klassefester lørdager og søndager når fritidsklubben ikke bruker lokalene selv. (Barn i alderen mellom 0-12 år, barnehagebarn og barneskole). Lokalene består av hallen, kafeen, diskotek og kjøkken. Diskoteket er utstyrt med: diskolys, musikkanlegg og har store speil på veggene.','Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'378',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='122'),'Fritidsklubb',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='30'),NULL,NULL,'Fritidsklubben er ungdommen egen tilholdsplass i bydelen, hvor man kan møte trygge voksne og "henge ut" eller være med på aktiviteter i et rusfritt miljø. Fritidsklubben leies også ut til barnebursdager når lokalet er ledig','Tirsdag 18:00-22.00 Klubb for ungdom 13-18 år Torsdag: 13.30-16.00 Juniorklubb for 5-7 klasse Torsdag: 18:00- 22.00 Klubb for ungdom 13-18 år Annenhver fredag i partallsuker Klubb for ungdom 13-18 år',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'379',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='122'),'Musikkstudio',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='43'),NULL,NULL,'Vårt musikkstudio vil bli utstyrt med profesjonell kapasitet og kan leies av alt fra glade amatører til profesjonelle aktører til innspilling av demo/plater/øvingslokale etc. Men er i første rekke prioriteres ungdommen som bruker fritidsklubben og leies kun ut til andre aktører ved ledig kapasitet.','Etter avtale',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'374',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='122'),'Rygja',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'Rygja er vår storstue hvor det kan holdes konserter med en publikums kapasitet på 450 personer. Salen er utstyrt med skyveamfi, lyd og lys anlegg med bransjestandard. Rygja kan også brukes til større konferanser og selskaper hvor det kan dekkes opp til selskap for 400 personer sittende, kombinert med vårt storkjøkken. Rygja kan også brukes til fysisk aktivitet men er ikke dimensjonert som idrettsanlegg. Det vil derfor ikke bli tillatt med f.eks ballspill etc. i salen, men lettere mosjon og fysisk aktivitet','Etter avtale',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'375',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='122'),'Greenroom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Møterrom for 10-15 personer','8.00.24.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'446',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='133'),'Slettå',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'Inngang A Slettå (storsalen) -et område for møter og samlinger med tilhørende kjøkken. Stort og fleksibelt område med plass til opptil 90 personer. Lokalet har et tilstøtende lager der det finnes 15 bord og 80 stoler som kan plasseres etter eget ønske. Rommet er godt utstyrt for ulike typer arrangementer: - Tre projektorer - Mikrofoner og høyttalere - Musikk kan spilles direkte fra mobiltelefon via Bluetooth. Kjøkkenet er fullt utstyrt og egner seg for både servering og matlaging, to stekeovner og to kokeplater, kjøleskap og fryser, to oppvaskmaskiner, samt to vasker. I midten av kjøkkenet står en stor arbeidsbenk for matlaging. Det er to arbeidsstasjoner for matlaging på kjøkkenet. Det finnes også gryter, stekepanner, mikser, kaffemaskin, vannkoker og annet nødvendig kjøkkenutstyr. Mellom kjøkkenet og salen er det serveringsvindu som kan lukkes ved behov, og det er en garderobe for yttertøy rett ved kjøkken. Tilrettelagt for eksempelvis: Større møter Sosiale samlinger Kulturlokaler, formidling Kulturlokaler, øving og verksteder Kunst, håndverk og media Praktisk info: Inngang A fra Renessøygata15 Utenfor åpningstid vil du få koden til døren tilsendt på sms 10 minutter før rommet er booket. Husk å legge inn nok tid til å rigge før og rydde etter bruk. Lokalet skal se like fint ut når du forlater det som da du kom. Ved behov for mopp eller andre rengjøringsartikler -finner du under vasken ved den store arbeidsbenken.','Mandag - søndag kl. 08.00 - 23.00. Dørene er åpne og ansatte er på lokalet mandag til fredag kl. 9 - 15. Utenom disse tidene brukes tilsendt kode på sms ved booking. Koden blir tilsendt 10 minutter før klokkeslettet du har booket lokalet fra.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'341',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='95'),'Disko',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='30'),NULL,NULL,'Diskoteket uten Dj. Det er ikke mulig å bestille DJ eller bruke deres egen. Rommet kan reserveres i sammenheng med bursdagsfester, klassefester osv. Rommet kan kun brukes i kombinasjon med kjøkkenet. Barnebursdager/skolefester er prioritert. Kobling til utstyret via Bluetooth på telefonen. Lag en spilleliste, koble til AEROLINK og spill din egen musikk. Volumet justeres med volum knappen. Discolys og alt utstyr er på når dere kommer, det er bare til å koble på og spille! Husk at musikken vil forsvinne om man tar mobilen med Bluetooth koblingen ut av rommet. Disco room without Dj. Not possible to book a DJ or use your own. The room can only be bo oked for birthday parties, class parties, etc. The room can only be booked combined with the kitchen. Children birthday parties/school parties are prioritised when booking the room. Easy connection to bluetooth in the room. Create a playlist, connect to AEROLINK and play your own music. The volume is adjusted with the volume button. Disco lights and all equipment are on when you arrive, it''s just to connect and play! Remember that the music will disappear if you take the phone with the Bluetooth connection out of the room.','Diskoteket kan bestilles kun i kombinasjon med Kjøkken/Kafè. Only available for booking together with the kitchen for various parties.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'478',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Frisørsalong',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'Frisørsalongen på Hundvåg bydelshus er et lyst og innbydende lokale som er tilrettelagt for frisørtjenester og velvære. Her finner du det meste som trengs for en god frisøropplevelse, inkludert komfortable frisørstoler, speil og annet relevant utstyr. Lokalet er utformet med fokus på både funksjonalitet, trivsel og tilgjengelighet. Det gir en trygg og hyggelig ramme for besøkende i alle aldre. Frisørsalongen er en del av bydelshusets inkluderende tilbud og bidrar til å gjøre Hundvåg bydelshus til et levende og omsorgsfullt møtested for nærmiljøet. Lokalet kan leies av personer eller virksomheter som ønsker å tilby frisørtjenester til beboere og besøkende i området. Noe av utstyret som vises på bildene følger med ved leie, men leietakere må påregne å ta med eget spesialutstyr, produkter og annet nødvendig materiell for å kunne drive virksomheten på en forsvarlig og profesjonell måte.','Vanlige uker: Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'302',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Kafèen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='28'),NULL,NULL,'Kafèen på Øyahuset har plass opp til 45 personer. (Vi har her 24 faste sitteplasser, for å utvide kapasitet henter man stol og bord fra storsalen) Rommet kan brukes til møter, mindre samlinger, kurs, dåp, konfirmasjon etc. Man må regne med at man til tider må dele kjøkken med brukere i storsalen. Ønsker man å benytte lokalet uten forstyrrelser, bes det om at dette spesifiseres på søknaden. Rommet har lydtett skyvedør til Hjørnet – rommet ved siden av, og kan benyttes ved en separat reservasjon. Dette rommet gir plass til +20 stykk. Rommet har også: barne-stoler, TV, projektor og høyttalere er tilgjengelig til hverdagsbruk, med HDMI, mikrofon og AUX ledning.','Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'301',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Kjøkken',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Kjøkkenet er velutstyrt og har dekketøy til ca. 100 personer. Kjøkken er et felles fasilitet for overetasjen på bydelshuset. Kjøkken er godkjent av mattilsynet og kan brukes til matlaging av mat til salgs. Dersom du i tillegg ønsker mer rom og trenger kjøkken bare for dere selv, så må du søke spesifikk om dette - i enkelte tilfelle må det beregnes sambruk av kjøkken.','Mandag: kl. 8:00 til 15:30 Tirsdag: kl. 8:00 til 16:00 Onsdag: kl. 8:00 til 15:30 Torsdag: kl. 8:00 til 16:00 Fredag: kl. 8:00 til 15:00 Lørdag og Søndag: stengt, ingen ansatte tilstede på bydelshuset',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'481',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Natteravnrommet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'Ett mindre rom i kjelleren som primært blir brukt av natteravnene. Kan brukes til oppbevaring eller kontor.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'24',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='21'),'Hovedbane kunstgress',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Banen har en spilleflate på 105 x 65 meter, og er hjemmebanen til FK Vidar sitt herre- og damelag.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'479',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='122'),'Treningsrom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'494',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='21'),'Tennisbane 2 (ny)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='45'),NULL,NULL,'På Tennisbane 1 og 2 på Lassa kan du reservere tid (maks 2 timer) her inne i Aktiv kommune. For å avbestille en booking, sender du en e-post til idrett@stavanger.kommune.no. Anlegget har en manuell lysbryter som gir deg lys i 2 timer.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'486',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='138'),'Selskapslokale',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='49'),NULL,NULL,'Informasjon om lokalet Tante Emmas hus er et hyggelig selskapslokale et steinkast fra Breiavatnet. Her kan du arrangere bryllup, selskap, dåp, julebord og andre sosiale sammenkomster. Lokalet egner seg også godt til møter og lignende arrangementer, da det er tilgjengelig både mikrofon, prosjektor og teleslynge. Det er tilgang til kjøkken med komfyr, kjøledisk, fryser, kaffetrakter, varmeplater, steameroppvaskmaskin og annet kjøkkenutstyr. Det finnes dekketøy til 50 personer, inkludert vannkarafler, serveringsfat og ulike typer stettglass. Det er tillatt å nyte medbragt alkohol ved lukkede arrangementer i Tante Emmas hus. Vi har også blomstervaser i ulike størrelser, telysholdere og elektriske telys til utlån. Av hensyn til brannsikkerheten er det ikke tillatt å bruke levende lys i lokalene eller utenfor inngangsdørene. Vi har ikke duker til utlån. Lokalet består av to stuer: en stor stue vendt mot Breiavatnet og en mindre stue vendt mot Kongsgata. Vi leier også ut møterommet vårt i 3 etasje. Det er personheis i bygget og eget HC-toalett. Leieprisen inkluderer utvask. Leietaker er imidlertid ansvarlig for oppvask og generell opprydding i lokalene. Før leieforholdet starter, må leietaker delta på en omvisning og opplæring i bruk av lokalet. Leietaker vil få informasjon om utlevering og innlevering av nøkkel under omvisningen. Tante Emmas hus sender ut tidspunkt for gjennomføringen av omvisning/opplæring, men leietaker ansvar for å etterspørre tidspunkt dersom dette ikke har blitt tilsendt. Aldersgrense ved leie Ved kveldsarrangementer må den ansvarlige for leieforholdet være over 25 år. Dette gjelder ikke ved dåp, konfirmasjon eller bryllup. Konfirmasjonssesong Ved utleie i helger med flere konfirmasjoner må lokalet være klargjort for utvask innen kl. 20.00. Vi åpner for booking fra 1. januar året før arrangementet skal finne sted. Kontaktinformasjon For arrangementer i våre åpningstider, eller dersom du har spørsmål, kan du kontakte oss på e-post: tante.emmas.hus@stavanger.kommune.no eller telefon 51 50 71 71 .',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'152',k.id,NULL,'Basseng',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='14'),NULL,NULL,'St. Svithun skolebasseng er på 16,6m x 10m. Dybden er 1,00 - 2,50m. Det er to garderober til bassenget. Det er foreløpig ikke mulig å søke om skolelokaler i Aktiv kommune. Søknadsfrist for kommende skoleår er 1.mars, søknadsskjema vil være tilgjengelig på Stavanger kommune sine nettsider i januar. Det kan være ledige enkelttimer i løpet av skoleåret, ta kontakt med idrett@stavanger.kommune.no. Stavanger kommune leier ut gymsal og basseng mandag-fredag kl.17.00-22.00 i perioden september-desember og januar-mai. Det er gratis å leie.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
