INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'487',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='139'),'Selskapslokale',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'28',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='21'),'Sandhåndballbane 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='44'),NULL,NULL,'Sandbane for sandhåndball og sandvolleyball.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'480',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Øvingslokal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='42'),10,'kilde','Øvingsrom for ungdommer i kjelleren for band og musikkgrupper Rommet er et fullt utstyrt øvingslokale med alt du trenger for bandprøver eller musikkøving. Det har: Trommesett med basstromme, skarptromme, toms og cymbaler Forsterkere for gitar og bass, inkludert flere kabinetter Tangentinstrument (keyboard) og mikrofonstativ med mikrofoner PA-mikser og kabler for tilkobling Komfortabel sofagruppe med bord for pauser Akustisk tilpasset rom med lydabsorberende vegger og gardiner Rommet passer for band, soloprosjekter eller mindre musikkgrupper som ønsker et godt sted å øve. Ta kontakt med Eirik Steffensen hvis du ønsker å bruke lokalen.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'493',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='21'),'Tennisbane 1 (ny)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='45'),NULL,NULL,'På Tennisbane 1 og 2 på Lassa kan du reservere tid (maks 2 timer) her inne i Aktiv kommune. For å avbestille en booking, sender du en e-post til idrett@stavanger.kommune.no. Anlegget har en manuell lysbryter som gir deg lys i 2 timer.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'489',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='103'),'Kontor/lagerrom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),5,'kilde','Dette kontoret har en pult som du kan låne hvis du trenger en kontorplass. Sendt en epost til epostadressen under hvis du ønsker å leie dette rommet.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'316',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='106'),'Møterom 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'Møterom 1 Plass til ca 15 stk Prosjektor og smart board. Skyvedører som kan stenges helt. Må gå igjennom Kafeen. NB! Det er kun mulig å booke ledig tid via kalender Nøkler skal hentes Tirsdagen før ditt arrangement mellom kl 18 - 19.00. Der blir da en gjennomgang av brannalarm, renhold og alarm. Tidspunktet du bestiller inkluderer forberedelser og renhold (rydding)','Åpningstider er 8 - 23 hver dag eller etter avtale Kontortid er Mandag 8-15.30 Tirsdag 10-19 Onsdag 8-15.30 Torsdag 10-19 Fredag 8-15 og i partall uker fri',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'319',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='106'),'Ungdomsklubben',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='30'),NULL,NULL,'Et koselig klubblokale som kun leies ut til barneselskap 6 -12 år. ( skolealder )barn for barn Lokalet kan leies LØRDAGER mellom kl. 13 - 16 og kl. 17- 20 og Søndag mellom 12-15. Det leies ikke ut i skolens sommerferie Hvis dere skal bruke diskoteket må dere ha DJ som koster kr 300,- for inntil 2 timer. Etter det er det 100 kr pr påbegynt time Dere må bestille dette på e-post: irene.meling@stavanger.kommune.no med det nøyaktige klokkeslett. Tiden dere leier inkluderer forberedelser og renhold(rydding)etter deres arrangement NB! Det er kun mulig å booke ledig tid via kalenderen. Nøkler skal hentes Tirsdagen før deres arrangement mellom kl 18 - 19.00. Det blir da en gjennomgang av brannalarm, renhold og alarm..','Åpningstider er mellom 8-23 hver dag ellers etter avtale Kontortid: Mandag: 8-15.30 Tirsdag: 10-19 Onsdag: 8-15.30 Torsdag: 10-19 Fredag: 8-15 (partallsuker fri)',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'351',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='115'),'Festlokale / møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='48'),NULL,NULL,'Grunnet fravær vil ikke søknader bli behandlet før 28.09.26 Fint og lunt rom for små selskaper. I dette rommet er plass til 32 mennesker (sittende) inne. Hvis du bruker uteområde, kan antallet deltakere være opptil 40 personer. Det kan dekkes til 32 personer på langbord. Ved lukket selskap kan det serveres alkohol. Vi gjør oppmerksom på at hagen er offentlig park og turområde. Ikke tillatt med dyr i lokalet. Andre utstyr og tillegg informasjon: - Uteleker og grill utstyr finner du kjelleren. Det er en bålplass og grill i uteområde. - To toaletter, en tilrettelagt for personer med nedsatt funksjonsevner - En hjertestarter i garderoben og rampe i kjelleren Informasjon i forhold til tidspunkter Arrangementer fredag/ lørdag avsluttes innen klokken 02:00. En forutsetter at uteaktiviteter etter klokken 23:00, da er det nattero i nabolaget. Ved leie fredag disponeres lokalet fra klokken 15:00 fredag til lørdag klokken 11.00 med mindre noe annet er avtalt. Leietaker plikter å ha lokalet rengjort og ryddet til lørdag klokken11.00. Ved leie lørdag disponeres lokalet fra klokken 11.00 lørdag til klokken 11.00 søndag. Leietaker plikter å ha lokalet rengjort og ryddet til klokken 11.00 søndag. Ved leie fredag og lørdag disponeres lokalet fra fredag kl.15:00 til søndag klokken 11:00. Leietaker plikter å ha lokalet rengjort og ryddet til søndag klokken 11.00.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'464',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='135'),'Ungdomsskole, ekskursjon',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='49'),NULL,NULL,'Dagsprogram og huskeliste Dagen varer fra ca 0900-1400 Klassene må deles inn i to like store grupper før en kommer til Lundsvågen: Snorkelgruppa utstyres med våtdrakter og snorkelutstyr. Så bærer det av sted i båt til et av de mange gruntvannsområder i skjærgården rundt Stavanger. Elevene har med hover som brukes til å samle små svømmende organismer. Vadegruppa utstyres med vadestøvler, vannkikkerter, hover og baljer. Vi kjører i båt til lange steinstrender eller sandstrender der vi vasser så langt støvlene rekker. Ved hjelp av utstyret vi har med, samler vi opp dyr og planter som er bunnlevende på grunt vann. Artene blir deretter så langt det lar seg gjøre klassifisert og brakt tilbake til Lundsvågen naturskole der vi stiller dem ut i akvariene. Mye av de minste rekene (mysidene) blir naturlig levende fôr til de små fiskeartene vi har i akvariene. Dagen avsluttes med grilling. Huskeliste for besøkende lærere og elever: Ankomst: Ta buss nr. 1A/1B fra Stavanger sentrum-Klubbgata ca kl 0830. Gå av ved Lunde skole/KIWI. Følg skiltene på den 10 min lange spaserturen til Lundsvågen naturskole. Avreise : Kl 1400. Gå til Lunde skole der buss nr. 1A/1B passerer. (Buss nr. 38 går fra Lundsvågen naturskole kl 1400, med bytte til buss nr.1 v/Kiwi. Mat : Alle elever tar med både matpakke (brødskiver/kjeks) og grillmat + drikke Klær : Regnklær, støvler, lue, vanter, ullsokker + ekstra sokker. Vi skal være ute hele dagen uansett vær, og været skifter ofte i løpet av en dag. Uansett er det mye kaldere på sjøen enn på land! NB! Snorkelgruppa må huske badetøy + håndkle. (Det er ikke mulighet å dusje etter snorkelsafarien) Betaling : Turen koster kr. 35,- pr. elev med minimum kr. 700,- pr. klasse. Lundsvågen naturskole sender regning. Sikkerhet : Alle bruker redningsvester som lånes på Lundsvågen naturskole. Våre lærere har livredningskurs. Bading : Besøkende elever får bare bade dersom dette på forhånd er avtalt med medfølgende lærer, og dersom denne har godkjent livredningskurs i.h.t.stavangerskolenes regelement. Klassens medfølgende lærer har da ansvar for sikkerheten! Fotoapparat : Anbefales, men husk at vi er i båt og ved sjøen hele dagen. Pass godt på så apparatet ikke faller i sjøen eller blir vått av sjøsprøyt. Spørsmål? Ring Bjørn Rugland 99737857.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'498',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='140'),'Ostalageret',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='49'),NULL,NULL,'Ostalageret er et mindre rom med lerret og projektor og lerret. Rommet har kapasitet til 70 personer. Det er 30 stoler og 4 bord tilgjengelig. Det er tilgang til felles kjøkken.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
