INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'205',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='78'),'Idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Idrettshallen har sportsgulv og er 23*44 m Denne hallen er klisterfri','Mandag-fredag kl.16-22.00 Lørdag kl.10.00-17.00 Søndag kl.11.00-18.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'501',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='80'),'Kampsportmatte 4',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='9'),NULL,NULL,'Kampsportmatte i 2.etg',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'314',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='106'),'Kafè',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='28'),NULL,NULL,'Ferie i uke 39 ingen behandling av søknader i denne perioden Vacation in week 39 no one to handel aplication before week 40 Kafeen kan leies alene eller sammen med storsal og kjøkken eller møterom 1 Det er plass til inntil 60 stk med bord og stoler som står fast i Kafeen. Det er gjennomgang til kjøkken og møterom 1 og 2 . Nøkler kan hentes Tirsdagen før ditt arrangement mellom kl 18 - 19.00. Det er da en gjennomgang av alarm, brannalarm og renhold. NB! Det er kun mulig å booke ledig tid via Kalender. Tidspunktet du bestiller inkluderer forberedelser og Renhold(rydding) etter arrangementet','Huset er åpent hver dag 8 - 23 (med nøkkelkort) Kontortiden: Mandag: 8 - 15.30 Tirsdag: 10 - 19 Onsdag: 8 - 15.30 Torsdag: 10 - 19 Fredag: 8-15 (partallsuker fri)',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'318',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='106'),'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'Ferie i uke 39 ingen behandling av søknader i denne perioden Vacation in week 39 no one to handel aplication before week 40 Storsalen er en stor forsamlingssal med bord og stoler til ca 150 stk. I tillegg er salen utstyrt med et enkelt tale anlegg, mikrofon, scene og projektor. teleslynge Den er god for trening, dans, selskaper, møter, teater, barneselskaper 3-12 år NB! Det er kun mulig å booke ledig tid via Kalender. Tidspunktet du bestiller inkluderer forberedelse og renhold(rydding)etter deres arrangement Nøkkel skal hentes Tirsdager før ditt arrangement mellom kl 18 - 19.00. Da vil det være gjennomgang av brann, renhold, og alarmsystem.','Huset er Åpent hver dag 8 - 23 Kontortid: Mandag: 8 - 15.30 Tirsdag: 10 - 19 Onsdag: 8 - 15.30 Torsdag: 10 - 19 Fredag : 8 - 15 (partall fri)',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'352',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='111'),'Studierom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='49'),NULL,NULL,'Studierom for 10 pers. Aktiv kommune er en portal til aktiviteter og ressurser. La kommunens ressurser; som for eksempel lokaler, anlegg, uteområder og utstyr komme enda flere innbyggere, lag og organisasjoner til gode gjennom utleie/utlån. Gjør de kommunale ressursene lettere tilgjengelig gjennom den digitale løsningen Aktiv kommune. Aktiv kommune er en digital tjeneste for leie og utlån av kommunens lokaler, anlegg, uteområder og utstyr. Kommunene får en digital saksbehandling og en plattform som kan brukes på tvers av avdelinger, og innbyggerne får en enkel selvbetjeningsportal.','Hele uken fra 08:00-16:00.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'271',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='95'),'Honningkrukka',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'Honningkrukka kan brukes til møter, undervisning og små selskap inntil 25 personer. Det er utstyrt med 2 møtebord, smart TV, to tavler (skrivesaker må medbringers, OBS - ikke permanente penner!) og en sofa. Piano er tilgjengelig på rommet. Rommet har ikke kjøkken. Alkohol er ikke tillatt. Dette i henhold til vedtak i kommunalstyret for oppvekst og levekår. Tidspunktet du bestiller inkluderer forberedelse og renhold. Renholdsrutiner, brannsikkerhet og innbruddsalarm vil bli gjennomgått ved henting av nøkler. English: The honey pot room can be used for meetings, teaching and small parties for up to 25 people. It is equipped with 2 meeting tables, a smart TV, two whiteboards (please bring your own writing pens, OBS - not permanent pens!) and a sofa. There is a piano in this room, too. This room has no kitchen. Alcohol is not allowed. This is in accordance with decisions in the municipal council. The time you book includes preparation and cleaning. Cleaning routines, fire safety and burglary alarms will be reviewed when collecting keys.','Gausel bydelshus er alltid åpent! Brukerne får nøkkel og tar ansvar for huset. Honningkrukka er åpen for leie hver dag: NB! Det er kun mulig å søke om ledig tid via kalenderen.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'274',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='95'),'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='31'),NULL,NULL,'Storsalen på Gausel bydelshus kan brukes til større møter, selskaper, trening, dans og undervisninger, men også teaterforestilling og konserter. Storsalen er godkjent av brannvesenet for 100 personer sittende med bord og stoler. Ønsker du å leie med kjøkkenfasiliteter må du sende en søknad om Kjøkken/Kafè i tillegg. Utleie kun til alkoholfrie arrangementer. Tidspunktet du bestiller inkluderer forberedelse og renhold. Renholdsrutiner, brannsikkerhet og innbruddsalarm vil bli gjennomgått ved henting av nøkler.','Gausel bydelshus er åpen alle dager! Brukerne får nøkkel og tar ansvar for bruk av huset. Storsalen er åpen for leie hver dag: NB! Det er kun mulig å booke ledig til via kalenderen.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'409',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='120'),'Innbyggerbussen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='43'),NULL,NULL,'Lån av Peugeot E-Traveller 8-seter Bussen kan kjøres med førerkort klasse B og har en rekkevidde på ca. 340 km. Den kan lånes av lag, foreninger, kommunedelsutvalg og kommunale enheter på Finnøy og Rennesøy. Leietaker må være minst 23 år og ha gyldig førerkort. Bilens hentes og bringes til ladestasjon utenfor Vikevåg innbyggertorg, Aslalveien 6, 4150 Stavanger. Pris Lag og foreninger: Gratis Kommunedelsutvalg: Gratis Kommunale enheter: 250 kr per dag Låner / leier av bussen betaler for bom / ferge Behandlingstid av søknad Regn tre virkedager på behandling av søknad, ta også høyde for helg, helligdager og ferietid. Henting og bruk Bussen hentes innenfor reservert tid. Nøkkel ligger i en nøkkelboks, og kode sendes på sms før leieperioden. Eller en kan hente nøkkel på torget i torgets åpningstider 8.30-15.00. Automatiske skyvedører må ikke dras opp. Leietaker er ansvarlig for rengjøring, lading og rapportering av skader. Forsikring og ansvar Bussen er forsikret, men leietaker må betale egenandel ved skade (4 000–10 000 kr). Feil og skader må meldes inn umiddelbart. Røyking er forbudt, og bussen må ikke brukes til ulovlige formål. Barneseter - Det finnes bilputer for barn på Frivilligsentralene på Finnøy og Rennesøy. Legg inn i søknaden under feltet: ( Kort beskrivelse av arrangementet / aktiviteten) , dersom det er ønskelig å låne puter',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'343',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='110'),'Muligheten',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='38'),NULL,NULL,'MØTEDELTAKERE - Max 20 personer. Romstørrelse: 31 m² Dette rommet er tilpasset til flere typer arbeid. Rommet har en lun og god sofa som kan deles opp 2 x 3 eller settes i sammen som en 5 seter. En kan plassere møblene etter det møteroms oppsettet en ønsker. Rommet skal innby til både jobb og kreativ tankegang og en lun samtaleplass i sofaen. Vanlig møte med flyttbar storskjerm Kreative prosesser Samtalerom for mindre grupper Møblene er flyttbare med hev og senk borde, stablestoler eller ergonomiske krakker. Eksempel på møteromsoppsett, se bilder. TEKNISKE FASILITETER WIFI - Sikkert høyhastighet trådløst bredbånd, kommunalt nettverk og gratis publikumsnett. LYS - dimming av lys, panel på vegg.','Møterom og drop-in arbeidsplasser: Mandag - fredag kl. 8 – 22. (møtet må være avsluttet og lokalene ferdig ryddet til kl. 22) Innbyggertorget er bemannet: mandag - fredag kl. 08.30 – 15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'337',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:stavanger' AND b.ekstern_id='110'),'Verkstaden',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:stavanger' AND kk.kodetype='lokaletype' AND kk.kode='38'),NULL,NULL,'MØTEDELTAKERE - Max 25 personer. Romstørrelse: 50 m² Dette rommet er tilpasset til flere typer arbeid. Rommet skal innby til både jobb og kreativ tankegang. Vanlig møte med eller uten video på storskjerm på vegg. Kreative prosesser. Presentasjoner og informasjonsmøter Møblene er flyttbare med sammenleggbare bord og stablestoler. I enden av rommet er det en stedsbygget benk med tilhørende hev og senk bord og stoler. Eksempel på møteromsoppsett: småbord og stoler, hestesko, langbord eller stoler som kinooppsett. TEKNISKE FASILITETER WIFI - Sikkert høyhastighet trådløst bredbånd, kommunalt nettverk og gratis publikumsnett. DIGITALT UTSTYR - 1 stor Samsung 85’’ 4K skjerm med både kablet og trådløs deling av dokumenter. VIDEOKONFERANSE Cisco LYD - rommet satt opp med en hodebøylemik og takmikrofon. I taket er det høyttalere som gir god talelyd i hele rommet. Det er integrert et topp moderne taleutjevninganlegg for å ivareta alle med nedsatt hørsel og/eller høreapparat. LYS - dimming av lys, panel på vegg. STRØM - i den stedsbyggede benken langs veggen er det strømuttak under benk og lademuligheter. Samt to strømuttak i taket','Møterom og drop-in arbeidsplasser: Mandag - fredag kl. 8 – 22. (møtet må være avsluttet og lokalene ferdig ryddet til kl. 22) Innbyggertorget er bemannet: mandag - fredag kl. 8.30 – 15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1103' AND fi.kildenokkel='aktiv-kommune:stavanger' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs_aktivitet (ressurs_id,aktivitet_id) SELECT r.id,m.aktivitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='aktivitet' AND kk.kode='48' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.aktivitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:stavanger' AND r.ekstern_id='70' ON CONFLICT DO NOTHING;
INSERT INTO ressurs_aktivitet (ressurs_id,aktivitet_id) SELECT r.id,m.aktivitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='aktivitet' AND kk.kode='29' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.aktivitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:stavanger' AND r.ekstern_id='33' ON CONFLICT DO NOTHING;
