INSERT INTO kommune (kommunenr,navn,fylkesnavn) VALUES ('3201','Bærum','Akershus') ON CONFLICT (kommunenr) DO NOTHING;
INSERT INTO fagsystem_instans (kildenokkel,type,navn,base_url) VALUES ('aktiv-kommune:baerum','booking','Aktiv kommune Bærum','https://baerum.aktiv-kommune.no') ON CONFLICT (kildenokkel) DO NOTHING;
INSERT INTO kommune_fagsystem_instans (kommune_id,fagsystem_instans_id,type) SELECT k.id, fi.id, fi.type FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (kommune_id,fagsystem_instans_id) DO NOTHING;
INSERT INTO kildekode (fagsystem_instans_id,kodetype,kode,navn) SELECT id,'lokaletype','6','Anlegg' FROM fagsystem_instans WHERE kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,kodetype,kode) DO UPDATE SET navn=EXCLUDED.navn, sist_sett=now();
INSERT INTO kildekode_mapping (kildekode_id,lokaletype_id,status,kartlagt_av) SELECT kk.id,t.id,'godkjent','etl' FROM kildekode kk JOIN fagsystem_instans fi ON fi.id=kk.fagsystem_instans_id, lokaletype t WHERE fi.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='6' AND t.kode='GENERELT_LOKALE' ON CONFLICT (kildekode_id) DO NOTHING;
