INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'44',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='28'),'BIP stort møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Bærum idrettspark stort møterom har kapasitet til 30 personer. For å booke møterom i Bærum idrettspark, ta kontakt med Bærum idrettspark på mikkel.rosok@baerum.kommune.no.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'284',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='38'),'Musikkrom - RYTMEBOKSEN',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='35'),NULL,NULL,'Musikk rommet er 78 m2 stort og inneholder en liten tribune for mindre opptredener. Musikkrommet er utrustet med et helt nytt piano merke Kawai. Musikkrommet inneholder også en stor Apple TV, samt høyttalere med bluetooth tilkopling. Det er lyse lokaler med god takhøyde i lokalet og industriparkett. Plass til: 25 personer. Sitteplasser / stoler 10.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'53',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='6'),'BIP utendørs kunstisbane bane 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,'For å booke tid på kunstisbanen skal Bærum idrettspark kontaktes på mikkel.rosok@baerum.kommune.no. Dersom flere utleieobjekter skal leies må utleieobjektene bookes samtidig. Dette gjøres enkelt i selve søknaden.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'41',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='5'),'BIP fotballhall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,'Bærum idrettspark er et kommunalt idrettsanlegg som består av en idrettshall, en friidrettshall, en fotballhall, et svømmeanlegg, møterom, en kunstisbane/tennisbaner, en rulleskiløype, en cricketbane/baseballbane og treningsapparater. Anlegget eies og driftes av Bærum kommune. Fotballhallen er en 9''erbane, men kan deles i mindre utleieobjekter. Dersom flere utleieobjekter eller hele hallen skal bookes må utleieobjektene bookes på samme tid. Dette gjøres enkelt ved å gå via det ene utleieobjektet.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'245',k.id,NULL,'Skolekjøkken (16p)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='1'),16,'kilde','Skolekjøkkenet er utrustet med 4 kokesoner for inntil 16 personer, kokekar og dekketøy. Lokalet passer godt for mindre grupper som vil lage mat sammen, enten for å teste en ny oppskrift eller for å spise en hyggelig middag sammen. Leietaker vasker og setter på plass lånt utstyr før lokalet forlates.','Mandag-torsdag: kl.17.00 - 21.30',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
