INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'211',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='29'),'Haslumhallen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Haslumhallen er tilrettelagt for håndball og volleyball. Idrettshallen har: 22x45m med 7m fri takhøyde Parkettgulv 4 garderober Oppmerking: Håndball: 1 matchbane Basketball: 2 treningsbaner Volleyball: 2 baner Haslumhallen eies av Bærum kommune, og driftes av Haslum IL. Det er ikke mulig å leie Haslumhallen gjennom kommunens bookingsystem. Haslum IL står for utleie av hallen. Kontakt geir(at)haslumil.no for utleie.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'285',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='38'),'Musikk / Dans - SPEILSALEN',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='35'),NULL,NULL,'Musikk rommet er 99 m2 stort og inneholder en lang speilvegg med ballett bar. Musikkrommet er utrustet med et helt nytt digitalt piano merke Yamaha. Musikkrommet inneholder også en stor Apple TV (75") og tilkobling via hdmi, samt høyttalere med bluetooth tilkopling. Det er lyse lokaler med god takhøyde i lokalet og sportsgulvparkett. Plass til: 25 personer. stoler tilgjengelig.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'74',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='20'),'Hoslehallen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Hoslehallen er tilrettelagt for håndball, basketball, volleyball og badminton. Idrettshallen har: 22x45m med 7m fri takhøyde Parkettgulv 4 garderober Oppmerking: Håndball: 1 matchbane, 3 minihåndball Basketball: 1 matchbane, 4 treningsbaner Volleyball: 3 baner Badminton: 4 baner Hoslehallen eies og driftes av Bærum kommune. Hallen leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'133',k.id,NULL,'Torg Skogen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Torg Skogen er uteleiedelen i Jar barnehage. Et ypperlig sted å avholde barnebursdag eller annen aktivitet for de minste barna. Utleiedelen består av garderobe, toaletter, 3 baserom med leker, et lite kjøkken med mikro, oppvaskemaskin, kjøleskap og stekeovn. I tillegg er det barnebestikk, tallerkener og kopper som kan brukes mot at det vaskes etter bruk. Torget Skogen er ikke egnet for lengre møter for voksne da det ikke er tilgjengelig høye bord og stoler i disse områdene.','Mandag- Fredag: 17.00-21.00',TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'150',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='14'),'Rykkinnhallen B',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Rykkinnhallen er for håndball, basketball, innebandy, badminton, volleyball, cheerleading, el-bandy og bordtennis. Hall B har: Størrelse på hele hallen er 25x45m, fri takhøyde 5m Parkettgulv Oppmerking: Basketball: 1 matchbane, 2 treningsbaner Håndball: 1 matchbane, 2 minihåndball Volleyball: 3 baner Innebandy: 1 bane Badminton: 4 baner Rykkinnhallen eies av Bærum kommune og driftes av Bærums Verk Hauger IF. Hall B leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'55',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='8'),'BIP svømmehall 50m bane 4 23m',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='25'),NULL,NULL,'Bærum idrettspark svømmehall er et kommunal svømmeanlegg. Det er 8 garderober i anlegget hvor alle er utstyrt med HC-toalett, to av garderobene har badstue og to av garderobene er tilpasset med et adskilt dusjrom. 50m basseng: Størrelse: 50m x 25m Dybde: 2m. Hev-senk: I ene halvdel av bassenget er det hev-senkbunn til 0m. På samme halvdel er det en hev-senkbrygge så banene kan deles i 25m og 23m. Temperatur: 28 grader I 50m bassenget er mulig å leie en bane eller forskjellige kombinasjoner av baner. Dersom flere baner eller hele basseng skal leies må antallet utleieobjekter bookes samtidig. Dette gjøres enkelt på selve bookingsiden ved å gå via et utleieobjekt.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'138',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='8'),'BIP svømmehall 50m bane 4 25m',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='25'),NULL,NULL,'Bærum idrettspark svømmehall er et kommunal svømmeanlegg. Det er 8 garderober i anlegget hvor alle er utstyrt med HC-toalett, to av garderobene har badstue og to av garderobene er tilpasset med et adskilt dusjrom. 50m basseng: Størrelse: 50m x 25m Dybde: 2m. Hev-senk: I ene halvdel av bassenget er det hev-senkbunn til 0m. På samme halvdel er det en hev-senkbrygge så banene kan deles i 25m og 23m. Temperatur: 28 grader I 50m bassenget er mulig å leie en bane eller forskjellige kombinasjoner av baner. Dersom flere baner eller hele basseng skal leies må antallet utleieobjekter bookes samtidig. Dette gjøres enkelt på selve bookingsiden ved å gå via et utleieobjekt.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
