INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'224',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='8'),'BIP svømmehall opplærings basseng 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='25'),NULL,NULL,'Bærum idrettspark svømmehall er et kommunal svømmeanlegg. Det er 8 garderober i anlegget hvor alle er utstyrt med HC-toalett, to av garderobene har badstue og to av garderobene er tilpasset med et adskilt dusjrom. Terapibasseng: Størrelse: 12,5x9,5m. Dybde: 0-1,60m. Hev-senk-muligheter i bassenget, med 8 ulike dybder. Temperatur: 32-34 grader. Opplæring/varmtvannsbasseng er mulig å leie halvt eller helt. Dersom en halvdel eller hele bassenget skal leies må antallet utleieobjekter bookes samtidig. Dette gjøres enkelt på selve bookingsiden ved å gå via et utleieobjekt.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
