INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'135',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='8'),'BIP svømmehall 50m bane 9 23m',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='25'),NULL,NULL,'Bærum idrettspark svømmehall er et kommunal svømmeanlegg. Det er 8 garderober i anlegget hvor alle er utstyrt med HC-toalett, to av garderobene har badstue og to av garderobene er tilpasset med et adskilt dusjrom. 50m basseng: Størrelse: 50m x 25m Dybde: 2m. Hev-senk: I ene halvdel av bassenget er det hev-senkbunn til 0m. På samme halvdel er det en hev-senkbrygge så banene kan deles i 25m og 23m. Temperatur: 28 grader I 50m bassenget er mulig å leie en bane eller forskjellige kombinasjoner av baner. Dersom flere baner eller hele basseng skal leies må antallet utleieobjekter bookes samtidig. Dette gjøres enkelt på selve bookingsiden ved å gå via et utleieobjekt.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
