INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'344',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='48'),'1C4 Kunnskapshjørnet v/kantinen (70p)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='42'),70,'kilde','Kunnskapshjørnet er en del av spisearealet i kantinen som kan stenges av. Rommet befinner seg i 1 etasje og har utsikt ut over Sandvikaelven og Rådhuset. Plass til 70 personer. Rommet er 155 m² stort.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'306',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='48'),'Idéverkstedet (21p)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='41'),21,'kilde','Idéverkstedet er et flott og lyst hjørnelokale som ligger i 1. etasje med inngang fra Møteplassen i Kommunegården. Det består av et rom (1C2 /1C3).Totalt areal er 96 m² og det er 21 sitteplasser fordelt på flere småbord. Rommet er utstyrt med AppleTV ( 75'''' skjerm), lydplanke og nødvendige kabler, Whiteboard og veggflater til å jobbe med. Av rekvisitter vil det være Post-its, gråpapir, tusjer og penner. Idéverkstedet er spesielt tilrettelagt for workshops og utviklingsprosesser. Aktiviteter i Idéverkstedet vil annonseres på skjermer på Møteplassen og vil være et viktig element for økt samskaping mellom kommunen og Bærumssamfunnet. Ønsker dere støtte til prosesser kan Innovasjon kontaktes på innovasjon@baerum.kommune.no .','Lokalene som bookes vil kun være tilgjengelige i ukedagen i perioden: mandag - torsdag: kl 08.00 - 22.00 fredag: fra kl 08.00 - 20.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
