INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'305',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='38'),'Møterom på sykehjemmet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='40'),NULL,NULL,'Møterommet egner seg til møter opp til 18 personer. Det ligger rett ved resepsjonen på sykehjemmet. Inngang fra generasjonsgata mellom sykehjemmet og barnehagen. 60" tv med hdmi kabel og apple tv. Mulighet for å bestille kaffe og boller/kaker/og annet ved bestilling.','Kl. 17.15-22.00 mandag til torsdag og 17.15-20.00 fredag.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'376',k.id,NULL,'Hundsund kunstis/kunstgressbane 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,'Hundsund kunstisbane har størrelse 110x72m.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'378',k.id,NULL,'Hundsund kunstgressbane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='11'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'288',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='38'),'Samlingssal - FERDINAND (1034 )',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='19'),NULL,NULL,'Samlingssalen Ferdinand er Oksenøya skoles største og flotteste lokaler med plass til nærmere 300 personer fordelt på et hele 291 m ² stort rom. Samlingssalen har også en stor scene og det er derfor godt egnet for å organisere større arrangementer som kurs, forelesninger, åpne møter, årsmøter til konferanser og seminarer. Ferdinand er utrustet med nytt AV-utstyr, lys- og lydanlegg, stort lerret med projektor som kan kobles til pc via hdmi. Samlingssalen Ferdinand har lyse lokaler, god takhøyde og industriparkett. Lokalet er utrustet med både runde bord (4 personer), lang bord (12-personer) og totalt 300 stoler til personer i kino oppsett, inklusivt sittebenker og bord helt bakerst i rommet. Siden lokalet har en stor scene og sceneteppe er lokalet godt egnet til teater og forestillinger. Lyskastere kan justeres på scenen og 4 mikrofoner (hvorav 2 mygg) er tilgjengelig og lyd kan kobles til høyttalere via ledning. I tilknytning til scenen er det også en egen elektrisk heis for forflytningshemmede og lokalet har flere innganger. Det er dessverre ikke anledning til å låne kjøkken eller servere mat som krever tilberedning på skolen. Størrelse Areal: 291 m ² Rom nummer Areal: 1034',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'377',k.id,NULL,'Hundsund kunstis/kunstgressbane 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='18'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'86',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='22'),'Studio 44',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='21'),NULL,NULL,'Vil du spille inn din egen podkast? Nå kan du booke Studio 44 på Bærum bibliotek Bekkestua for å spille inn podkast eller andre lydinnspillinger. For å booke studioet må du være minst 18 år. Første gang du benytter Studio 44, må du ha med legitimasjon og signere en brukeravtale. Studioet har plass til maks fire personer. Det er tilrettelagt for opptak av tale og egner seg ikke som øvingslokale for musikk. Studio 44 er utstyrt med: 1 x RØDECaster Pro miksepult 4 x Røde / Audio Technica mikrofoner + kabler 4 x hodetelefoner Opptaket gjøres og lagres på RØDECasteren. Du må ha med egen PC, Mac eller annen enhet for å overføre opptaket med USB-kabel. For mer info om hvordan opptak med mikseren fungerer, kan du klikke deg inn på denne lenken: https://rode.com/en/user-guides/rodecaster-pro Studio 44 er selvbetjent. Trenger du 15 minutters opplæring, ta kontakt på barum@barum.bib.no for å avtale dette. Åpningstider Studio 44: mandag-torsdag 10.00-17.30 fredag-lørdag 10.00-15.30 I juli reduseres åpningstidene i henhold til bibliotekets betjente åpningstid: mandag-torsdag 10.00-17.30 fredag 10.00-15.30 lørdag 10.00-14.30',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'99',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Konferanserom 103-104',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,'Dette er et konferanserom med opptil 30 plasser. Rommet ligger sentralt i 1. etasje, rett ved kaffebaren Kunnskapskoppen. Rommet er spesielt godt egnet til gruppearbeid. Rommet har tre tavler. Det finnes to prosjektorer i rommet som kan brukes hver for seg eller sammenkoblet. Standard er at de er sammenkoblet. Dette rommet ligger også i nær tilknytning til auditoriet, og kan fungere som et ekstra grupperom, bevertningsrom eller avlastningsrom. Areal: 82 m²',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
