INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'12',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='55'),'Undervisningsbasseng bane 1 - Nadderudhallen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='25'),NULL,NULL,'Nadderudhallen svømmehall undervisningsbasseng. Bassenget kan deles i to, og det er mulig å leie en halvdel. Dersom flere baner eller hele bassenget skal leies må utleieobjektene bookes samtidig. Dette gjøres enkelt på selve bookingsiden ved å gå via et utleieobjekt.','Mandag-fredag: 08:00-20:00 Lørdag og søndag: 10:00-16:00 Billettsalg avsluttes en time før stengetid.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
