INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'98',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Auditorium 101/102',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='19'),NULL,NULL,'Auditoriet er en flott aula for alt fra kurs, forelesninger, åpne møter til konferanser og seminarer. Lokalet har to innganger, heis for forflytningshemmede, moderne AV-utstyr og lyd- og lysanlegg. AV-utstyret ble oppgradert i uke 45 2022. Har også blitt oppgradert med mulighet for streaming. Klikk her for mer informasjon om vårt streamingtilbud . Det er også mulig å leie et piano til dette lokalet. Nærliggende grupperom kan benyttes ved behov. Areal: 278,8 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
