INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'59',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='11'),'Anna Krefting skole idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Idrettshall for volleyball, basketball trening, badminton, minihåndball og allidrett. Idrettshallen har: 26x33m med 7m fri takhøyde Punktelastisk sportsdekke 4 garderober Oppmerking Volleyball: 2 treningsbaner Basketball: 2 treningsbaner Badminton: 4 baner Håndball: 1 minihåndball Anna Krefting skole idrettshall eies og driftes av Bærum kommune. Hallen leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'69',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='45'),'Levre skole idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Levre skole idrettshall er tilrettelagt for basketball, volleyball, badminton og minihåndball. Idrettshallen har: 24x16m med 7m fri takhøyde GULV? 4 garderober Oppmerking: Basketball: 1 matchbane, 2 treningsbaner Volleyball: 1 matchbane Badminton: 3 treningsbaner Håndball: 1 minihåndball Levre skole idrettshall eies og driftes av Bærum kommune. Hallen leies kun ut som hel hall.','Mandag-torsdag: 08.00-22.00 Fredag-søndag: stengt',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'266',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='6'),'BIP cricket/baseball',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='10'),NULL,NULL,'En kombinert baseball/softball og cricketbane. Det er treningspitchbur på anlegget. For å booke tid på banen skal Bærum idrettspark kontaktes på mikkel.rosok@baerum.kommune.no. Dersom flere utleieobjekter skal leies må utleieobjektene bookes samtidig. Dette gjøres enkelt i selve søknaden.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'122',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Grupperom 314',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='9'),NULL,NULL,'Dette er et hyggelig grupperom i 3. etasje. Rommet har moderne AV-utstyr, og har plass til 8 personer. På veggen henger kunst av Unni Lund. Areal: 19,4 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'179',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Møterom 319',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Dette er et møterom med god atmosfære, i 3. etasje. På veggen her finnes et grafisk trykk med navnet «Passage in yellow» som passer fint inn i det gule rommet. Rommet har moderne AV-utstyr, og har plass til 16 personer. Areal: 29,3 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'214',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='15'),'Storstua',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='19'),NULL,NULL,'Forsamlingssal med scene. Utmerket til større møter, bursdager, konfirmasjon, dåp, forestilling osv. Lydanlegg og noe scenelys. Oppkobling til storskjerm. Bord og stoler tilgjengelig for ca. 120 personer. Rommet har kapasitet til 250 personer. Godt utstyrt kjøkken rett ved lokalet til matlaging. Servise (glass, tallerken, skåler og bestikk må evt. leietaker ta med selv). Priser: Det er gratis utlån til barn/foreldre på skolen til bursdager, klassetreff osv. fra mandag til onsdag mellom 17.15-21.15. Merk gjerne søknaden med type arrangement og elevens klasse. Utlån i helger til skolens elever ved bursdager og klassetreff er dessverre ikke mulig. FAU og korpset har gratis utlån. For utleie er prisene: Inntil 4 timer: 660,- Ny pris per 01.01.2026 : kr. 1 000,- Egne priser for utleie i helg. Vi leier/låner ikke ut lokaler i skolens ferier. Søknaden vil bli behandlet og bekreftet av en saksbehandler innen 3-5 arbeidsdager. Bruk kalenderen for å se ledige datoer.','Mandag til onsdag 17.15-21.15 Fredag til søndag etter avtale. Merk at utleie i helg vil avhengig av om vi har tilsynsvakt tilgjengelig.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
