INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'113',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Konferanserom 459',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,'Flott hjørnerom med utsyn mot Engervannet og Løkkeåsen/Evjeåsen. Rommet har store vindusflater med mye naturlig lys. I rommet finnes også et akrylmaleri av Helge Røed. Areal: 76,8 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'72',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='18'),'Evje skole idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Evje skole idrettshall er tilrettelagt for basketball, volleyball, badminton og minihåndball. Idrettshallen har: 16x26m med 7m fri takhøyde Sportsdekke 2 garderober Oppmerking: Basketball: 1 treningsbane Volleyball: 1 matchbane, 2 treningsbaner Badminton: 2 baner Håndball: 1 minihåndballbane Evje skole idrettshall eies og driftes av Bærum kommune. Hallen leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'73',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='19'),'Storøya skole idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Storøya skole idrettshall er tilrettelagt for basketball, volleyball, badminton, innebandy og minihåndball. Idrettshallen har: 20x32m med 7m fri takhøyde Punktelastisk gulv 4 garderober Oppmerking: Basketball: 1 matchbane, 2 treningsbaner Volleyball: 1 matchbane Badminton: 4 baner Håndball: 2 minihåndballbaner Innebandy: 1 bane Storøya skole idrettshall eies og driftes av Bærum kommune. Hallen leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'120',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Møterom 479',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Stort, og svært lyst hjørnerom i 4. etasje. Utsikten er noe begrenset av nybygget, man har fortsatt fin utsikt ned på Stasjonstorget og jernbanen, samt Evjeåsen med Bærum sykehus på toppen. Rommet har moderne AV-utstyr og har plass til 18 personer. Areal: 40,5 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'105',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Konferanserom 220',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,'Dette er et stort og luftig konferanserom med vinduer på hele den ene kortveggen. Rommet har plass til 70 personer i klasseromsoppsett og 60 personer i grupperomsoppsett innenfor stolpene i rommet. (Se bilder). Plass til noen flere bord langs vinduene. Godkjent for opptil 80 personer. Utstyrt med moderne AV-utstyr. Rommet har i tillegg utstyr for streaming. Klikk her for informasjon om vårt streamingtilbud . Areal: 126,8 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'112',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Konferanserom 309/354',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='20'),NULL,NULL,'Flott hjørnerom med utsyn mot Løkkeåsen og Evjeåsen, i 3. etasje. Rommet har store vindusflater med mye naturlig lys. Rommet har moderne AV-utstyr, og har plass til 40 personer. På veggen finnes kunst av Svallaug Svalastoga og Vilhelm Tveteraas. Areal: 73,6 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'263',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='37'),'Hundsund bad undervisningsbasseng 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='25'),NULL,NULL,'Dersom flere baner eller hele bassenget skal leies må utleieobjektene bookes samtidig. Dette gjøres enkelt på selve bookingsiden ved å gå via et utleieobjekt.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'56',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='9'),'Helsethallen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Idrettshall for håndball, basketball, badminton og volleyball. Idrettshallen har: Størrelse på hallen er 22x45m, inkludert f ri takhøyde 7m Syntetisk flateelastisk idrettsdekke 4 garderober Oppmerking: Håndball: 1 matchbane, 2 minibane Volleyball: 3 baner Basketball: 1 matchbane, 4 treningsbaner Badminton: 4 baner Helsethallen eies og driftes av Bærum kommune. Hallen leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'17',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='3'),'BIP idrettshall 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Bærum idrettspark er et kommunalt idrettsanlegg som består av en idrettshall, en friidrettshall, en fotballhall, et svømmeanlegg, en kunstisbane/tennisbaner, en rulleskiløype, en cricketbane/baseballbane og treningsapparater. Anlegget eies og driftes av Bærum kommune. Bærum idrettspark idrettshall er tilrettelagt for håndball uten klister, basketball, tennis, badminton, innebandy og volleyball. Idrettshallen har: 23x44m med 7m fri takhøyde Kombielastisk gulv 4 garderober Oppmerking: Håndball: 1 matchbane, 2 minihåndball Basketball: 1 matchbane, 2 treningsbaner Volleyball: 1 matchbane, 3 treningsbaner Badminton: 1 matchbane, 8 treningsbaner Innebandy: 1 bane Tennis: 3 baner Innebandy: 1 bane Idrettshallen kan deles i to, og består av to utleieobjekter. Skal hele hallen bookes må begge utleieombjektene bookes på samme tid. Dette gjøres enkelt ved å gå via det ene utleieobjektet.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'256',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='37'),'Hundsund bad 25m-basseng bane 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='25'),NULL,NULL,'Dersom flere baner eller hele bassenget skal leies må utleieobjektene bookes samtidig. Dette gjøres enkelt på selve bookingsiden ved å gå via et utleieobjekt.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'96',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Auditorium 101',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='19'),90,'kilde','Auditorium 101 har plass til 90 personer, og er ideelt til alt fra kurs, forelesninger, åpne møter til konferanser og seminarer. Auditoriet har moderne AV- utstyr (oppgradert i november 2022) og lyd- og lysanlegg. Det er også mulig å leie et piano til dette lokalet. Auditorium 101, kan slås sammen med auditorium 102, og vil da bli en stor aula, med plass til 220 personer, og har da to lerret til eventuelle fremvisninger. Nærliggende grupperom kan benyttes ved behov. Areal: 119,5 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'57',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='10'),'Hundsundhallen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Hundsundhallen er tilrettelagt for håndball, basketball, volleyball, innebandy og badminton. Idrettshallen har: 25x45m med 7m fri takhøyde Parkettgulv Garderober deles med svømmehallen Oppmerking: Håndball: 1 matchbane, 3 minihåndball Basketball: 1 matchbane, 3 treningsbaner Innebandy: 1 bane Badminton: 7 baner Volleyball: 3 baner Hundsundhallen eies og driftes av Bærum kommune. Halles leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'213',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='15'),'Musikkrom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='35'),NULL,NULL,'Øvingsrom for små grupper. Mulighet for oppkobling av lyd og video på skjerm. Speilvegg med barre. Stort dansegulv og kortrapper. OBS! Ikke egnet for feiring av bursdager. Det er gratis utlån til barn/foreldre på skolen til bursdager, klassetreff osv. fra mandag til onsdag mellom 17.15-21.15. Merk gjerne søknaden med type arrangement og elevens klasse. Utlån i helger til skolens elever ved bursdager og klassetreff er dessverre ikke mulig. FAU og korpset har gratis utlån. For utleie er prisene: Inntil 4 timer: 550,- Vi leier/låner ikke ut lokaler i skolens ferier. Bruk kalenderen for å se ledige datoer. Søknaden vil bli behandlet og bekreftet av en saksbehandler innen 3-5 arbeidsdager.','Mandag til onsdag 17.15-21.15 Fredag til søndag etter avtale. Ved utleie i helg gjelder andre priser, ta kontakt for mer informasjon.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'111',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Konferanserom 354',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'Hjørnerom med utsyn mot Løkkeåsen og Evjeåsen, i 3. etasje. Rommet har store vindusflater med mye naturlig lys. Rommet har moderne AV-utstyr, og har plass til 20 personer. Rommet kan slås sammen med rom 309 , og vil da ha plass til 40 personer. Areal: 40,2 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'124',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Grupperom 316',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='9'),NULL,NULL,'Hyggelig grupperom i 3. etasje. Rommet har moderne AV-utstyr, og har plass til 8 personer. I rommet finnes flotte små bilder av kunstner Rus Mesic. Areal: 15,4 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'101',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Datarom 215',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='21'),NULL,NULL,'Dette er et flott datarom som ligger i 2. etasje i Kunnskapssenteret. Rommet har 24 datamaskiner og er ustyrt med smartboard. Godkjent for 28 personer. Areal: 68,5 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'202',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='24'),'Konferanserom 326',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,'Dette er et stort og flott rom som ligger i 3. etasje, med utsyn over Stasjonstorget og det nye Helgerudkvartalet. Har plass til 120 personer. Er en del av Spiseriet mellom klokken 11-13, men kan lukkes og brukes som separat konferanserom. Rommet har store vindusarealer og slipper inn mye naturlig lys. Rommet har moderne AV-utstyr, oppdatert 28. november 2025. Areal: 155 m² Veiledende priser for eksterne firmaer/kunder: Klikk her for prisoversikt for eksterne firmaer/kunder Dersom du søker på vegne av en avdeling internt i Bærum kommune skal du legge ved organisasjonsnummeret til ditt tjenestested. Egne interne priser. Prisene justeres årlig med virkning fra 1. januar.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'1',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='1'),'Nadderudhallen idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Nadderudhallen er tilrettelagt for håndball uten klister, basketball og volleyball. Idrettshallen har: 25x45m med 7m fri takhøyde Parkettgulv 4 garderober Oppmerking: Håndball: 1 matchbane, 2 minihåndballbaner Basketball: 1 matchbane, 3 treningsbaner Volleyball: 1 matchbane, 3 treningsbaner Nadderudhallen eies og driftes av Bærum kommune. Hallen leies kun ut som hel hall.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'16',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='3'),'BIP idrettshall 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Bærum idrettspark er et kommunalt idrettsanlegg som består av en idrettshall, en friidrettshall, en fotballhall, et svømmeanlegg, en kunstisbane/tennisbaner, en rulleskiløype, en cricketbane/baseballbane og treningsapparater. Anlegget eies og driftes av Bærum kommune. Bærum idrettspark idrettshall er tilrettelagt for håndball uten klister, basketball, tennis, badminton, innebandy og volleyball. Idrettshallen har: 23x44m med 7m fri takhøyde Kombielastisk gulv 4 garderober Oppmerking: Håndball: 1 matchbane, 2 minihåndball Basketball: 1 matchbane, 2 treningsbaner Volleyball: 1 matchbane, 3 treningsbaner Badminton: 1 matchbane, 8 treningsbaner Innebandy: 1 bane Tennis: 3 baner Innebandy: 1 bane Idrettshallen kan deles i to, og består av to utleieobjekter. Skal hele hallen bookes må begge utleieombjektene bookes på samme tid. Dette gjøres enkelt ved å gå via det ene utleieobjektet.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'405',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:baerum' AND b.ekstern_id='57'),'Møterom Fornebu bibliotek',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:baerum' AND kk.kodetype='lokaletype' AND kk.kode='1'),10,'kilde',NULL,'Mandager 09.00-16.00 Tirsdager 09.00-16.00 Onsdager 09.00-16.00 Torsdager 09.00-18.00 Fredager 09.00-16.00 Lørdager 11.00-15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='3201' AND fi.kildenokkel='aktiv-kommune:baerum' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs_aktivitet (ressurs_id,aktivitet_id) SELECT r.id,m.aktivitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='aktivitet' AND kk.kode='106' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.aktivitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:baerum' AND r.ekstern_id='285' ON CONFLICT DO NOTHING;
