INSERT INTO ressurs_fasilitet (ressurs_id,fasilitet_id) SELECT r.id,m.fasilitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='fasilitet' AND kk.kode='1' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.fasilitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:baerum' AND r.ekstern_id='6' ON CONFLICT DO NOTHING;
