INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'37',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='11'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Knappskog gymsal eller Knappskoghallen blir lånt ut gjennom www.aktivivest.no Fast treningstider blir fordelt gjennom fordelingsnøkkel og sammen med idretten i Øygarden kommune. Størrelsen på hallen er: Lengde: 24m Bredde: 16m Høyde: 7m','Følger skolen sin skolerute Mandag - fredag 0800-2200',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'301',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='112'),'Møterom - Straume BUS',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),NULL,NULL,'Møterommet på Straume bu og servicesenter ligg midt i senteret. Tilkomst gjennom senterets hovedinngang. Parkering er tilgjengeleg på øvere plan i parkeringshuset (du treng ikkje parkeringsløyve per dags dato). Kvm: ca. 35 Maks antal personar i lokale: ca. 20 personar. Du må stå for dekketøy sjølv. Utstyr: projektor (HDMI), mikrofon med teleslynge. Retningslinjer: - Det er ikkje tillet å konsumera alkohol i lokalet. - Forlét lokalet slik du møtte det. Leigetakar er ansvarleg for å vaske/rydde etter bruk av lokalet (vaskeutstyr er tilgjengeleg). Boss tømmer du på bossrommet. Øvrig informasjon: - Det er kun eit avgrensa antal bord og stolar på møterommet til vanleg. Ekstra bord og stoler er tilgjengeleg på lager. - Kjøken er ikkje tilgjeneleg for utleie. - Tilstøtande lokale er ikkje tilgjengeleg for utleie og skal ikkje nyttast. - B enytt dere av toalett ved garderoben i kantina. - OBS! Ver merkam på at tilstøtande lokala kan være leid ut samtidig med utleige av møterommet. Møterommet på Straume bu og servicesenter er mogeleg å booke: Måndag-fredag fra 15:30-21:30. Senterets opningstider: 07:30-15:30 Kontaktinformasjon resepsjon: 56160440','Møterommet på Straume bu og servicesenter er mogeleg å booke: Måndag-fredag fra 15:30-21:30.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
