INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'24',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='6'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Gymsal knytt til Hjelteryggen skule. Storleik på gymsalen er: 169m2 og scene på 64m2.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'116',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='23'),'Ågotnes idrettsanlegg - Friidrettsanlegg 400 m løpebane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Løpebanen er banen rundt gressbanen, 7 felt på kunstdekke. Et friidrettsanlegg kan både være et fullt tradisjonelt stadionanlegg med 6, 7 eller 8 400 meter lange rundbaner, et anlegg med redusert antall baner og et delanlegg uten rundbaner, hvor de enkelte disipliner (få eller mange) kan plasseres slik det passer på det enkelte sted. Alle friidrettsanlegg som legges med fast dekke i Norge skal legges med selvdrenerende dekke over en drensasfalt. Dekket skal tilfredsstille en europeisk standard. Dekkets leverandør skal ha et sertifisert dekke blant IAAFs sertifiserte leverandører. Det anbefales sterkt at i prosessen for å finne leverandør brukes "Standard konkurransegrunnlag for friidrettsdekker" som forefinnes på Kulturdepartementets Idrettsavdelingens nettsider http://www.idrettsanlegg.no/ . Dette sikrer rette spesifikasjoner og etterfølgende tester som sikrer at man har fått levert det man har betalt for. Det er også en vesentlig fordel om man skulle være uheldig og kan brukes som underlag for reklamasjon. Ta gjerne kontakt for veiledning.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'344',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='116'),'Kulturlokalet',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='45'),NULL,NULL,'Lokalet er KUN til bruk for Øygarden kulturskule',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
