INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'62',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='2'),'Speleflate',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Består av ei handballbane med tribuneanlegg til tre hundre menneske, møterom og garderobeanlegg med seks garderobar. Oppmerking av baner: 1.stk handballbane 3.stk basketballbaner på tvers av hallen. 1.stk basketballbane på senter av hallen 3.stk volleyballbaner på tvers av hallen 1.stk volleyballbane på senter av hallen 5.stk badmintonbaner',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'300',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='112'),'Kantina - Straume Bu & Servicesenter',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='27'),NULL,NULL,'Kantina på Straume bu og servicesenter ligg i hjarte av senteret. Tilkomst gjennom senterets hovedinngang. Dette er et ope lokale med gjennomgang til andre deler av bygget. Parkering er tilgjengeleg på øvere plan i parkeringshuset (du treng ikkje parkeringsløyve per dags dato). Kvm: ca. 130 Maks antal personar i lokaet: 80 personar. Det kan dekkes til mellom 60 og 80 (du må stå for dekketøy sjølv). Utstyr: projektor (VGA), mikrofon/musikkanlegg med teleslynge. Retningslinjer: - Det er ikkje tillet å konsumera alkohol i lokalet. - Forlét lokalet slik du møtte det. Leigetakar er ansvarleg for å vaske/rydde etter bruk av lokalet (vaskeutstyr er tilgjengeleg ). Boss tømmer du på bossrommet. Øvrig informasjon: - Det er kun eit avgrensa antal bord og stoler i kantina til vanleg. Ekstra bord og stoler er tilgjengeleg på lager. - Kjøken er ikkje tilgjeneleg for utleie. - Tilstøtande lokale (dagavdelinga) er ikkje tilgjengeleg for utleie. - OBS! Ver merkam på at tilstøtande lokala kan være leid ut samtidig med utleige av kantina. Kantina på Straume bu og servicesenter er mogeleg å booke: Måndagar fra 15:300-21:30 Tysdagar fra 15:30-21:30 For spørsmål kan du kontakta institusjonen i kontortid (07:30-15:30). Senterets opningstider: 07:30-15:30 Kontaktinformasjon: 56160440','Kanina på Straume bu og servicesenter er mogeleg å booke: Måndagar fra 15:30-21:30 Tysdagar fra 15:30-21:30 For spørsmål kan du kontakta institusjonen i kontortid (07:30-15:30).',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'12',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='12'),'Symjehall - Ågotnes skule',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Fasiliteter i Ågotnes symjehall: 25 m basseng med baner Badstu Normaltemperert Tildelt treningstid gjeld bruk av basseng inkludert dusjing og tid i garderobe. For å få flyt i omkleding/dusjing kan ein kunne nytta garderobeområde samstundes ved skifte av grukargruppe. Slik overlapping må dei ulike gruppene avtala seg imellom. Dersom ein ikkje kjem til einighet om overlapping vert garderobetid inkludert i tida. Vis omsyn og respekt for andre brukarar ved å halde tidene som er tildelt.','Åpningstider off. bading: Tirsdager: 17.30 – 20.45 Torsdager: 17.30 – 20.45',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'249',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='58'),'Symjehall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Det er offentleg bading i symjehallen på Stranda skule tysdagar og torsdagar. Dersom ein skal nytta seg av vaksenbading må ein vere over 15 år. Utleigeplanen viser opningstider for offentleg bading, samt fordeling av tid i symjehallen for dei ulike organisasjonane. Symjehallen opnar 1. september og følgjer elles skuleruta. Symjehallen er difor stengt i feriar.','Tysdag Torsdag Familiebading: kl. 17.00 - 20.00 Familiebading: kl. 16.00 - 20.00 Vaksenbading: kl. 20.00 - 22.00 Vaksenbading: kl. 20.00 - 22.00 Pris: Barn kr. 15,- Vaksen kr. 30,-',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
