INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'42',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='3'),'Møterom 3.etg',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),NULL,NULL,'Møterom i 3 etg med plass til ca 25 - 30 personer Rommet storleik er: 43,4m2. Rommet har AV utstyr til bruk. Møte må være avsluttet til kl 2200. Møterommet har tilgang gjennom e-lås - kode blir sendt på SMS i forkant av starttid.','Følger Sotra Arena sine åpningtider. Møter skal være avsluttet en halv time før stengetid for hallen.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'145',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='81'),'Storsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='26'),210,'kilde','Lokalet har sitteplass til 210 personer i storsalen. Salen er oppsatt som et amfi med fastmonterte seter (210) og scene på gulvplan. Toalett ligg ved småsalen, skal og vera tilgjengelig for brukere av storsalen, dersom det er to arrangement samtidig. KJøkkenet skal deles mellom begge rom. Rommet er lite egnet til besøk o.l.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'222',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='2'),'Garderobe 5',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='30'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'204',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='52'),'Speleflate',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Speleflate',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'104',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='34'),'Skodespelarfoajeen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='37'),NULL,NULL,'Skodespelarfoajeen ligg i bakkant av Straume kulturhus. Der er det plass til ca 15-20 personer. Rommet kan og brukes til møterom og har digitale hjelpemidler til møter. I samme lokaler er det tilgang til garderober og toaletter. For reservasjon, kontakt innbygger torget v/Torill Martinsson (56161637) om ledig tid og booking av lokale. Kulturhuset er digitalisert og oppgradert med nytt utlån system. Du treng i utg.pkt ikkje henta nøkkel. Du vil får ein kode på SMS eller e-post kort tid før din leigeperiode skal væra. Det er da særs viktig at du legg inn rett e-post og mobilnummer i søknaden. Dette er du sjølv ansvarlig for er rett. Vakt vil IKKJE låsa opp dersom det er leigetakar som har gjort feil. Vilkår som vert lagt vekt på i høve prioritering av leigetakarar: Frivillige lag og organisasjonar tilhøyrande i Øygarden kommune Kulturarrangement/framsyningar Kulturøvingar Andre leigetakarar Gratis å leige for lag/organiasjoner i Øygarden kommune. Gebyr for andre leigetakarar.','Mandag - torsdag - 0800 - 2200 Fredag 0800 - 2300 Lørdag/søndag 0800 - 2300 Anna tid kan avtales ved søknad',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'329',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='48'),'Flo - Straume Bibliotek',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),16,'kilde','Møterom 3.etg - s torleik ca 20 kvm Bord og stolar til ca 10-12 personar Stor Tv skjerm med kamera Må ha med egen pc Innbyggartorg og bibliotek på Sartor Storsenter Måndag: 10.00 – 16.00 Tysdag: 10.00 – 16.00 Onsdag: 10.00 –16.00 Torsdag: 12.00 – 19.00 Fredag: 10.00 – 16.00 Laurdag: 10.00 – 15.00 Møteromma på Øygarden innbyggjartorg og bibliotek har no direkte bestilling . Det inneber at møteromma kan reserverast utan å gå vegen om administrasjonen. Bestillinga skjer via bookingportalen www.aktivivest.no , og romma kan bookast innanfor gjeldande opningstider. Eventuelle spørsmål om bruk av romma eller teknisk utstyr kan rettast til innbyggjartorget eller biblioteket. Er rommet ledig, så vil du få tilgang til rommet i den tida du har bestilt rommet. 1. For booking av dette rommet, må du velge tidsrom til høgre. 2. Etter at du har valgt tidsrom, må du identifisere deg med MIN-ID/Bank-ID 3. Når du har fått godkjent møterom/lokal vil du få en e-post NØKKEL TIL MØTE ETTER OPNINGSTID, MÅ HENTES I OPNINGSTIDA TIL INNBYGGARTORGET PÅ STRAUME.','Innbyggartorg og bibliotek på Sartor Storsenter Måndag: 10.00 – 16.00 Tysdag: 10.00 – 16.00 Onsdag: 10.00 –16.00 Torsdag: 12.00 – 19.00 Fredag: 10.00 – 16.00 Laurdag: 10.00 – 15.00 Innbyggartorg og bibliotek på Sund Senter og Rong Senter Måndag: 10.00 - 16.00 Tysdag: 10.00 - 16.00 Onsdag: meirope* Torsdag: 12.00 - 19.00 Fredagar: 10.00 – 16.00 Laurdag: meirope* *Meirope (ubetent): Innbyggjarar kan få tilgang til innbyggjartorga/biblioteka i opningstida til sentera gjennom å inngå eigen avtale.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'307',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='48'),'Bibliotekscene - Straume Bibliotek',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
