INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'189',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='89'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Gymsal knytt til Rong skule.','Følger skuleruta til Rong skule',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'305',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='82'),'Dansesal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='2'),NULL,NULL,'Lokale i inngangspartiet av Hjeltefjorden Arena og symjehall.','Følger hallen sine åpningstider',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'310',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='1'),'Klasserom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),30,'kilde','Møterom i Bildøyhallen med plass til 30-40 personer. Rommet blir også nytta til klasserom for Sotra Vidaregåande skule. Møterommet i Bildøyhallen har direkte booking. Er rommet ledig for du låne det fortløpende, uten godkjenning av sakshandsamar. Direktebooking av rommet gjelder fra kl 1600-2200, mandag til fredag. Er rommet opptatt vil søknaden bli sendt inn til sakshandsamar.','Mandag - fredag : 1600 - 2200 Lørdag og søndag til arrangement.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'49',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='3'),'VIP møterom 3.etg',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),70,'kilde','VIP rommet har plass til 70 personer. Rommet sin str er på 76,3 m2. Rommet har AV utstyr for bruk. Møte må være avsluttet til kl 2200. Hallen stenger kl 2230. Møterommet har tilgang gjennom e-lås - kode blir sendt på SMS i forkant av starttid.','Følger Sotra Arena sine åpningtider. Møter skal være avsluttet en halv time før stengetid for hallen.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'322',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='7'),'Allegretto',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='45'),25,'kilde','Lokale for korps, kor, musikk og dans. Rommet blir primært brukt til kulturskoleundervisning. Rommet er normalt i bruk alle ukedager. Rommet kan brukes fredag ettermiddag og helg. Rommet er et "tomt" rom, og det er ikke lagt opp til stoler og bord. Rommet har dansegulv, som treng varsom håndtering. Rommet er skofritt. Mat og drikke (unntatt vann) skal ikke nytes i rommet. NB: Dette er ikke et lokale for møter eller feiringer.','Fredag - søndag',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'328',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='48'),'Fjøre - Straume bibliotek',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),14,'kilde','Møterom 3.etg - s torleik ca 25 kvm Bord og stolar til ca 12 – 14 personer Stor Tv skjerm med kamera Må ha med egne pc Innbyggartorg og bibliotek på Sartor Storsenter Måndag: 10.00 – 16.00 Tysdag: 10.00 – 16.00 Onsdag: 10.00 –16.00 Torsdag: 12.00 – 19.00 Fredag: 10.00 – 16.00 Laurdag: 10.00 – 15.00 Møteromma på Øygarden innbyggjartorg og bibliotek har no direkte bestilling . Det inneber at møteromma kan reserverast utan å gå vegen om administrasjonen. Bestillinga skjer via bookingportalen www.aktivivest.no , og romma kan bookast innanfor gjeldande opningstider. Eventuelle spørsmål om bruk av romma eller teknisk utstyr kan rettast til innbyggjartorget eller biblioteket. Er rommet ledig, så vil du få tilgang til rommet i den tida du har bestilt rommet. 1. For booking av dette rommet, må du velge tidsrom til høgre. 2. Etter at du har valgt tidsrom, må du identifisere deg med MIN-ID/Bank-ID 3. Når du har fått godkjent møterom/lokal vil du få en e-post NØKKEL TIL MØTE ETTER OPNINGSTID, MÅ HENTES I OPNINGSTIDA TIL INNBYGGARTORGET PÅ STRAUME.','Innbyggartorg og bibliotek på Sartor Storsenter Måndag: 10.00 – 16.00 Tysdag: 10.00 – 16.00 Onsdag: 10.00 –16.00 Torsdag: 12.00 – 19.00 Fredag: 10.00 – 16.00 Laurdag: 10.00 – 15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
