INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'299',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='82'),'Symjehall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,NULL,'Onsdagar kl. 17.00 - 21.00 Laurdagar kl. 10.00 - 15.00 Søndagar kl. 10.00 - 15.00 Kontaktinformasjon: Øyane svømmeklubb post@oyanesvomming.no telefon: 476 43 583 Utenom dette er det satt opp treningstider til de ulike svømmeklubbane',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'7',k.id,NULL,'Bildøy Idrettsanlegg - Grusbane 2',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Bildøy idrettsanlegg - Fotballbane Grusbane 2, lengst fra Fjell Ungdomskule, kan kun lånast/leigast ut etter kl 1500 på kvardagar. For bruk av banar til arrangement, som t.d bobilparkering, sirkus o.l, skal dette avklarast i god tid med Fjell Ungdomsskule og tiltak som sikrar omårde skal setjast inn. Underlag: Grus Banetype: 11er Belysning: 150 lux Lengde: 91 Bredde: 50 Kan og brukes til: Underlag: Grus Banetype: 7er Belysning: 150 lux Lengde: 40 Bredde: 40',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'6',k.id,NULL,'Bildøy idrettsanlegg - Grusbane 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='24'),NULL,NULL,'Bildøy idrettsanlegg - Fotballbane Grusbane 1 Grusbane 1, nærast Fjell Ungdomskule, kan kun lånast/leigast ut etter kl 1500 på kvardagar. For bruk av banar til arrangement, som t.d bobilparkering, sirkus o.l, skal dette avklarast i god tid med Fjell Ungdomsskule og tiltak som sikrar omårde skal setjast inn. Underlag: Grus Banetype: 11er Belysning: 150 lux Lengde: 91 Bredde: 50 Kan og brukes til: Underlag: Grus Banetype: 7er Belysning: 150 lux Lengde: 40 Bredde: 40 Bana kan kun leigast etter kl 1500 på kvardager, grunnet bruk til Fjell Ungdomskule.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'146',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='81'),'Småsalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='27'),NULL,NULL,'Rong kulturhus småsalen er egna til mindre besøk, opp til 70 personer. Rommet har bord og stoler tilgjengelig, samt et lite kjøkken. Kjøkkenet må evt. deles med andre leietakere i storsalen, dersom det er arrangement der. Toalett i gangen må også deles. Småsalen kan deles inn i 3 mindre rom, med foldevegger mellom rommene. Lokalet er og lagt til rette som eit livssynsnøytralt seremonirom for Øygarden kommune. Et livssynsnøytralt seremonirom er et lokale som kan brukes av alle, uavhengig av livssyn, til seremonier som begravelser, bryllup og konfirmasjoner. Det er utformet slik at det ikke har faste religiøse symboler og kan tilpasses ulike seremonier.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'165',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='82'),'Møterom1 (sosialt rom)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),40,'kilde','Rommet skal inneholder 8 bord og 24 stoler satt opp ved veggen i nord. Sosialt rom er eit aktivitet- og møterom med ein kapasitet på 43 personar. Rommet inneheld: Tekjøkken: vannkoker og kaffitraktar, te og kaffikanne Multimediautstyr: trådlaus mikrofonar (1 Handheld + 1 headset), projektor med fjernkontroll og lerret (hdmi-kabel henger ut fra veggen), fastmonterte høgtalarar (minijack kabel henger ut fra veggen), 9 stikkontakter og 2 nettverks uttak (ikke kabel).','Følger åpningstider til hallen',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'195',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='51'),'Speleflate 3 - nord',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'9',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='23'),'Ågotnes idrettsanlegg - Kunstgrasbane 11ar bane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'Kunstgrasbane knytt til Ågotnes Idrettsanlegg. I vekedagene brukar Tranevågen ungdomskule bana mellom kl 0800-1430. For bruk av bana mellom desse tidspunkta kontakt skulen først før ein legg inn søknad om lån av bana. Besøksadresse Hamramyra 20 5353 Ågotnes Normann Mollandsøy (vaktmester) Tilsynsvakt epost Normann.mollandsoy@oygarden.Kommune.no Tilsynsvakt telefon: 41799695','Mandag - fredag: 0800-2200 Lørdag - søndag: 0900-2100',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'8',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='23'),'Ågotnes Idrettsanlegg - Grasbane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='23'),NULL,NULL,'Naturgrasbane - bruksperiode april - november . 11er naturgrasbane (Ågotnes gress) Lengde ca. 105 m, bredde 65 m, kommunal drift I vekedagene brukar Tranevågen Ungdomskule bana mellom kl 0800-1430. E-Post normann.mollandsoy@fjell.kommune.no Telefon 41799695 Besøksadresse Hamramyra 20 5353Ågotnes Tilsynsvakt namn Normann Mollandsøy (vaktmester) Tilsynsvakt epost Normann.mollandsoy@oygarden.Kommune.no Tilsynsvakt telefon 41799695',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'313',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='23'),'Ågotnes idrettsanlegg - Friplassen 200 m løpebane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='4'),NULL,NULL,'Friplassen kan være et godt alternativ til et stort friidrettsanlegg på steder med dårlig økonomi, og plass og på steder hvor man ønsker å støtte opp med et rekrutteringsanlegg til et nærliggende «stor stadion». Anlegget er kalt "Friplassen". Det lille anlegget innbyr til allsidighet og utvikling av viktige basisferdigheter hos barn og unge. En rekke utredninger viser at den fysiske formen hos barn og unge utvikler seg i foruroligende retning. Alle prognoser viser at dette vil skape store samfunnskostnader i framtiden. Idretten gjør en kjempeinnsats, men det er en 80 – 20 fordeling, hvor 20 % av de som vokser opp vil stå for minst 80 % av de framtidige samfunnskostnadene. Disse 20 % er som regel ikke aktive i idrettslagene. Friplassen skal være et tilbud til alle, ikke bare de som er interessert i idrett. Friidrett er den mest allsidige idretten med øvelser som stiller krav til spenst, styrke, hurtighet og kondisjon – på alle nivåer fra de som har evner og lyst til å drive idrett til de som «slenger med» på det som er «kult». FRIPLASSEN er tenkt brukt først og fremst ved skoler hvor den kan benyttes både i skoletiden og fritiden. Men FRIPLASSEN kan selvsagt også plasseres på idrettsanlegg og i nærmiljøer på steder hvor det er naturlig. Hele FRIPLASSEN er dekket av kunstdekke og er tilrettelagt også for andre idrettsaktiviteter som basketball, volleyball, turn, bandy og fotball. FRIPLASSENs store fordel er at den er liten og intim. Den dekker snaut 3 dekar og er et ypperlig utgangspunkt for et godt sosialt miljø.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'161',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='85'),'Toftøy idrettanlegg - Kunstgrasbane',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='22'),NULL,NULL,'Toftøy idrettsanlegg er eit moderne nærmiljøanlegg med kunstgrasbane av typen 9er , tilrettelagt for både trening og kampaktivitet. Bana har kunstgress med sand , måler 72 x 50 meter , og er utstyrt med 150 lux flomlys , noko som gjer ho godt egna for bruk heile året. Anlegget er kommunalt drifta',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'196',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='85'),'Toftøy idrettsanlegg - Klubblokale- møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='10'),NULL,NULL,'Lite møterom på Toftøy idrettsanlegg og kan leies til møter',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'43',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='3'),'Aktivitetsal-dansesal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='2'),NULL,NULL,'Aktivtetsrom til bruk for annan idrett, t.d dans, boksing og annan idrett som ikkje treng bruka arenaløysingar og idrettshall.','Føl hallen sine opningstidar',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'206',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='86'),'Foaje',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='37'),NULL,NULL,'Foajeen på skulen kan leigast. Det er 100 stolar tilgjengleg i foajeen. Prosjektor og stort lerret.','Følger skuleruta og åpningstider til skulen',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'290',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='108'),'Styrkerom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='20'),NULL,NULL,'Føremål: Eit styrkerom i ei idrettshall skal: gi høve til eigenorganisert styrketrening (kun rehabilitering) støtte basistrening for lag og enkeltutøvarar vere eit trygt, tilgjengeleg og funksjonelt rom for ulike brukargrupper Drift og tilgang: Aldersgrense 16 år Krav om innføring/opplæring før bruk Tilgang styrt av nøkkelkort og opningstider','Føl idrettshallen sine opningstide',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
