INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'60',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='3'),'Speleflate 2 - midt',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Speleflate 2 er gulvet av: Sportsgulv, kombielastisk. Rommet storleik er på 1151,5 m2 Speleflate 2 med oppmerking av følgjande: 1. stk Handballbane 6. stk Badmintonbaner 3. stk Basketballbaner 2. stk Volleyballbaner Festepunkt for turn. Pereskoptribune for publikum kan nyttast for 2/3 av hallen. Ved arenaløsning må både bane 1 og 2 nyttast. Da er det plass til 3200 publikum. Ved arenaløsning og publikum over 2100, kan ikkje hall 3 nyttast.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
