INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'25',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='7'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Liljevatnet skule er frå hausten 2019 barnehage og kulturskule Skulen har eigen gymsal/forsmalingslokale på 207 m2. Rutinar for utleige: Følgjer skuleruta for skulen og Øygarden kommune. Leigetakar må sjølv følgja med når skulen/gymsalen er stengt. Skulen er stengt i alle ferier og helligdager. Nøkkelhenting i barnehagen si åpningstid 0900-1500/1630. Dersom nøkkel ikke blir hentet i rett tid, blir det dessverre ikke låst opp. Det er ikkje tillate med alkoholservering i barne- og ungdomsskular unnateke det kombinerte anlegget på Bjorøyna, jfr. Opplæringslova § 9-5 3. ledd. Det er ikkje tillate med alkoholservering i barnehagar Ved godkjenning av dokumenter knytt til søknaden, er å rekna som juridisk bindane.','Mandag - torsdag 0800-2200 Fredag 0800-2200 (kun arrangement) Lørdag - søndag 0900-2200',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'19',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='5'),'Gymsal',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='7'),NULL,NULL,'Gymsal knytt til Brattholmen skule. Gymsalen har ein storleik på 162m2. Har og scene som er knytt til gymsalen.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'103',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='34'),'Kultursalen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='26'),NULL,NULL,'For reservasjon Straume kulturhus, kontakt innbygger torget v/Torill Martinsson (56161637) om ledig tid og booking av lokale. Straume kulturhus har plass til totalt 330 personar. Amfiet har plass til 220 personar. Kulturhuset er digitalisert og oppgradert med nytt utlån system. Du treng i utg.pkt ikkje henta nøkkel. Du vil får ein kode på SMS eller e-post kort tid før din leigeperiode skal væra. Det er da særs viktig at du legg inn rett e-post og mobilnummer i søknaden. Dette er du sjølv ansvarlig for er rett. Vakt vil IKKJE låsa opp dersom det er leigetakar som har gjort feil. Kriterium/vilkår for utlån: Vilkår som vert lagt vekt på i høve prioritering av eksterne leigetakarar: Born og unge busett i Øygarden kommune. Frivillige lag og organisasjonar tilhøyrande i Øygarden kommune Kulturarrangement/framsyningar Kulturøvingar Gratis å leige for lag/org. i Øygarden kommune. Gebyr for andre leigetakarar. Ikke utleige til private arrangement og privat personer. Leigetakarar som ønskjer fast avtale må søkja på nytt kvart år. Søknadsfrist er innan 1. mai året før nytt leigeår. Utleigeperiode er fra 1. august - 30. juni.','Mandag - torsdag - 0800 - 2200 Fredag 0800 - 2300 Lørdag/søndag 0800 - 2300 Anna tid kan avtales ved søknad',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'327',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='19'),'Testrom (vanligbooking)',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='33'),NULL,NULL,'Testrom ved Fjell skule Fjell skule har eit eige testrom som kan nyttast til prøvar, testar, kartleggingar og andre aktivitetar som krev rolege omgjevnader. Rommet er tilrettelagt for elevar som har behov for skjerming eller særskild tilrettelegging under gjennomføring av prøvar og testar. Bruk av rommet Rommet kan nyttast etter avtale med skulen. Det skal vere ro og orden i rommet under bruk. Utstyr og inventar skal behandlast varsamt. Eventuelle tekniske behov må meldast frå om på førehand. Tilrettelegging Elevar med vedtak eller dokumenterte behov for særskild tilrettelegging kan få nytte testrommet etter vurdering frå skulen. For spørsmål om bruk eller reservasjon av testrommet, ta kontakt med administrasjonen ved Fjell skule.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'114',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='19'),'Tjukkasmatte 1',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='34'),NULL,NULL,'Blå tjukkasmadrass Den blå tjukkasmadrassen er tilgjengeleg for bruk ved aktivitetar som krev ekstra sikring, demping eller tilrettelegging. Madrassen skal nyttast på ein trygg og forsvarleg måte og berre til føremål han er laga for. Retningslinjer for bruk Madrassen skal plasserast på eit flatt og stabilt underlag. Kontroller at madrassen er heil og utan skadar før bruk. Hopping, leik og aktivitet skal skje under ansvarleg tilsyn. Madrassen skal ikkje flyttast utan avtale eller nødvendig opplæring. Etter bruk skal madrassen setjast tilbake på anvist plass. Tryggleik Madrassen reduserer risiko for skade, men eliminerer ikkje risiko ved fall eller aktivitet. Brukarar må følgje gjeldande reglar og instruksjonar frå ansvarleg personell. Ved spørsmål om bruk av den blå tjukkasmadrassen, ta kontakt med ansvarleg for anlegget eller bygget.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'15',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='27'),'Symjehall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='3'),NULL,NULL,'Vi tilbyr trening i varmtvassbasseng. Bassenget har ein gjennomsnittstemperatur på 33,9 grader. Det er 12,5 meter langt og er utstyrt med boblebad, massasjebenk, massasjedyser, vannmassasjestråle, motstraumsanlegg. Det er tilgang til badstue (85 grader). Bassenget er tilrettelagt for funksjonshemma med velutstyrt handikapgarderobe. Behandling/trening i vatn kan fremja fysisk funksjon og lindra smerter ved ei rekke funksjonsvanskar. Oppdrift frå vatnet gjer at ein kan bevega seg lettare og med mindre smerte. Motstand i vatn gjev effektiv trening. Priser: Voksen: 65,-kr Barn: 50,- kr Barn under 2 år: gratis Kort og kontant betaling. Klippekort 10 klipp : Voksen: 585,-kr Barn: 450,- kr Opp av bassenget 15 min før stenging hver dag. Det er påbudt med badehette i Straume Terapibad. Dette har vi for salg, inkl. div. annet svømmeutstyr Fasiliteter i Straume Terapibad: 12,5 m basseng med barnedel Boblebad Motstrøm Massasjedyser Vannmassasje stråle Badstu ( 85 grader ) Handikap garderobe og stolar 34 grader varmt vatn!','Åpningstider Fredager: 16.00 – 20.00 Lørdager: 10.00 – 15.00 Søndager:10.00 – 15.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'350',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='3'),'Garderobe 4',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='30'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'332',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='3'),'Kafe-foaje',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='37'),NULL,NULL,'Kaféen i Sotra Arena er et uformelt møtested for både idrettsutøvere, foreldre, besøkende og folk som er innom anlegget på Straume. Den ligger sentralt i arenaen og er kjent for å tilby enkel, sunn og variert mat. Typiske tilbud i kaféen er: Ferske baguetter og smørbrød Smoothies og yoghurt Kaffe, brus og andre drikkevarer Vafler og bakevarer Enkel lunsj- og middagsmat Kaféen drives av Sotra Sportsklubb Kafé & Catering Atmosfæren er typisk for et moderne idrettsanlegg: lys, romslig og familievennlig, med utsikt til aktivitetene i arenaen. Den fungerer ofte som et naturlig samlingspunkt før, under og etter treninger, kamper og arrangementer. For deg som jobber med hallene i Øygarden, er kaféen også et viktig sosialt møtested i Sotra Arena der klubbfolk, foresatte og frivillige treffes på tvers av idretter.Kaféen i Sotra Arena er et uformelt møtested for både idrettsutøvere, foreldre, besøkende og','Mandag - fredag 1100- 1900 Lørdag og søndag 1000-1600',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'59',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:oygarden' AND b.ekstern_id='3'),'Speleflate 1 - nord',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:oygarden' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Speleflate 1 er gulvet av: Sportsgulv, kombielastisk. Rommet storleik er på 1147,5 m2 Speleflate 1 med oppmerking av følgjande: 1. stk Handballbane 6. stk Badmintonbaner 3. stk Basketballbaner 2. stk Volleyballbaner Festepunkt for turn. Pereskoptribune for publikum kan nyttast for 2/3 av hallen. Ved arenaløsning må både bane 1 og 2 nyttast. Da er det plass til 3200 publikum. Ved arenaløsning og publikum over 2100, kan ikkje hall 3 nyttast.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4626' AND fi.kildenokkel='aktiv-kommune:oygarden' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs_aktivitet (ressurs_id,aktivitet_id) SELECT r.id,m.aktivitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='aktivitet' AND kk.kode='123' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.aktivitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:oygarden' AND r.ekstern_id='189' ON CONFLICT DO NOTHING;
