INSERT INTO bygning (kommune_id,navn,bydel_navn,fagsystem_instans_id,ekstern_id,hjemmeside,epost,telefon,apningstid_tekst) SELECT k.id,'Stetindhallen','Kjøpsvik',fi.id,'24','0',NULL,NULL,'Ingen faste åpningstider. Hallen åpnes hovedsaklig i forbindelse med organiserte treninger, kulturarrangementer og andre arrangementer. For å benytte treningsrommet eller leie hallen gjelder følgende: Treningskort: Du kan kjøpe treningskort til hallen på Servicesenteret i Kjøpsvik, som holder åpent mandag til fredag fra 08:00 til 15:30. Leie og priser: Hallen kan leies på time- eller døgnbasis via Narvik kommune. Hvis du trenger informasjon om spesifikke treningstider for idrettslagene eller adgang med treningskort, anbefales det å kontakte Narvik Kommune direkte på telefon 76 91 20 00' FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT DO NOTHING;
