INSERT INTO bygning (kommune_id,navn,bydel_navn,fagsystem_instans_id,ekstern_id,hjemmeside,epost,telefon,apningstid_tekst) SELECT k.id,'Ballangen svømmehall','Ballangen',fi.id,'31','https://www.narvik.kommune.no/innbygger/tjenester/kultur-idrett-og-fritid/idrett-og-fritid/svommehaller/ballangen-svommehall/','postmottak@narvik.kommune.no','90 94 83 40','Ordinære åpningstider: Mandag: kl. 08.30–10.00 (Fellesbad), kl. 16.00–19.30 (Fellesbad) Tirsdag: kl. 12.00–13.30 (Voksenbad) Onsdag: kl. 10.00-12.00 (Elevfri bad. Gjelder fra 4. juni), kl. 12.30–13.30 (Babybad 0- 2 år) (garderobetid fra kl. 13.30 –14.00) Torsdag: kl. 14.00-15.00 (HC- bad), kl. 15.00 – 18.00 (Fellesbad), kl. 18.00 – 19.30 (Voksensvømming) (garderobetid fra kl. 19.30 – 20.00) Fredag: kl. 14.00–15.00 (Damebad) (Garderobetid fra 15.00 – 15.30), kl 14.20–14.45 (Aqua Aerobic), kl. 16.00–19.30 (Fellesbad) (garderobetid fra kl. 19.30 – 20.00) Lørdag: Kun åpent siste lørdagen i måneden, kl. 10.00–13.30 (Fellesbad)' FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT DO NOTHING;
INSERT INTO adresse (bygning_id,adressetekst,postnummer,poststed,geokoding,er_hovedadresse) SELECT b.id,'Storhaugveien 20','8540','Ballangen','ukjent',TRUE FROM bygning b JOIN fagsystem_instans fi ON fi.id=b.fagsystem_instans_id WHERE fi.kildenokkel='aktiv-kommune:narvik' AND b.ekstern_id='31' ON CONFLICT DO NOTHING;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'220',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:narvik' AND b.ekstern_id='28'),'Glassgang 2.08.B',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:narvik' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Rommet befinner seg i 2 etasje. Plass til x antall personer. Rommet er 121,30 m² stort.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'19',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:narvik' AND b.ekstern_id='2'),'Ankenes skole 4-7',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:narvik' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'&lt;p&gt;Storskola består av klasserom, grupperom, kantine, kultursal og glasshuset. Glasshuset passer til møter, avslutninger og annen sosial sammenkomst. &lt;/p&gt;',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
