INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'176',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:narvik' AND b.ekstern_id='21'),'Turnhallen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:narvik' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Turnhallen ligger i 1 etasje og er 1155,50 m². Hallen er fullt utstyrt med godkjente konkurranseapparater for turn kvinner og turn menn, inkludert skranke, svingstang, ringer, bøylehest, bom og hoppanlegg. For innløring av avanserte elementer og trygg landing, har hallen skumgummigroper og tykke sikkerhetsmatter. Hallen har egne flater tilrettelagt for troppsgymnastikk, med tumblingbaner og trampetter for høye svev. Hallen ble bygget i et felles prosjekt sammen med den nye Narvik Ungdomsskole. Det betyr at skoleelevene kan bruke turnhallen og flerbrukshallen som er vegg i vegg til kroppsøving på dagtid, mens Narvik Turnforening overtar lokalet til organiserte treninger på ettermiddagene og kveldene.','Hallen brukes av Narvik Ungdomsskole på hverdager mellom 08:30 og 14:40 . Narvik Turnforening har sine faste partier mandag til fredag mellom 15:00 og 21:00 . Hallen kan leies av eksterne (skoler, barnehager, bedrifter) utenom de faste treningstidene på dagtid og i helgene.',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
