INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'151',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:narvik' AND b.ekstern_id='17'),'Apollo',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:narvik' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Ungdomsklubb med utstyr for biljard, bordtennis, air hockey, Gaming, kreative rom. Kjøkken med sone for bord og stoler. Apollo er en åpen og inkluderende møteplass for ungdom i Narvik kommune. Tilbudet er gratis for alle i aktuell aldersgruppe, både fastboende og besøkende i Narvik og omegn. På klubbkveldene serverer vi gratis kveldsmat, og det er alltid to voksne til stede. Apollo ungdomsklubb er primært forbeholdt klubbdrift og kommunale aktiviteter, og leies derfor som hovedregel ikke ut til privat eller ekstern bruk. Målgruppe Junior: 5. klasse til og med 7. klasse Ungdom: 8. klasse til og med 17 år','Åpningstider Junior Tirsdager kl. 17.30-20.30 Junior har påmelding i Spond. Åpningstider Ungdom Mandager og onsdager: kl. 18.00-21.00 Fredager (oddetallsuker): kl. 18.00-22.00',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
