INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'4',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:narvik' AND b.ekstern_id='3'),'Ankenes hallen , hel hall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:narvik' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Fullmerket for blant annet håndball, volleyball, basketball og badminton. Tribune med ordinær sitteplasskapasitet på ca 150 tilskuere. Hele hallen har sportsgulv og utgjør 1070 m² Det er ikke tillatt å bruke sko med sorte såler i idrettshallen. Vennligst bruk innesko med lyse eller ikke-merkende såler.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'12',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:narvik' AND b.ekstern_id='3'),'Kafeteria / Møterom',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:narvik' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Kafeteria har oppsett med bord og stoler. Kjøkken er utstyrt med salgsdisk, kaffetrakter, kjøleskap, samt steke og kokemuligheter. Innerste del av kafeteria kan skilles av med foldevegger for møter eller samlinger. Kafeteria har størrelse 56,1 m² Møterom har størrelse 31,4 m² Ved utleie skal kjøkken vaskes etter bruk og det skal ikke etterlates mat eller annet utstyr. Bord og stoler settes tilbake på plass på en ryddig måte.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='1806' AND fi.kildenokkel='aktiv-kommune:narvik' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
