INSERT INTO ressurs_aktivitet (ressurs_id,aktivitet_id) SELECT r.id,m.aktivitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='aktivitet' AND kk.kode='6' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.aktivitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:narvik' AND r.ekstern_id='134' ON CONFLICT DO NOTHING;
