INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'10',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:afjord' AND b.ekstern_id='2'),'Kino',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:afjord' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Kinosalen er først og fremst designet for å gi gode film- og kinoopplevelser. Salen har totalt 70 seter, der 2 av plassene er tilrettelagt for rullestolbrukere. Salen har audiovisuelt utstyr som gjør den godt egnet til kurs, konferanse- og mindre konserter. Lydanlegget ivaretar alle lydformater opp til 7.1 kinolyd.',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='5058' AND fi.kildenokkel='aktiv-kommune:afjord' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'9',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:afjord' AND b.ekstern_id='2'),'Blackbox',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:afjord' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'• 223 - 300 personer Blackbox er storsalen i Å!. Salen har plass til 221 personer i amfi, der 3 av plassene er tilrettelagt for rullestolbrukere. Salen er tilpasset for ulike sceneproduksjoner, med lyd og lyssystemer av god kvalitet. Salen har audiovisuelt utstyr slik at man enkelt kan gjennomføre kurs, konferanser og foredrag. Salen kan også brukes med flatt gulv, og kan rigges med bord og stoler, eller for et stående publikum. Høytalerflate: Nexo Geo Touring Lydmikser: Midas HD96 Heritage Lysmikser: grandMA3 onPC',NULL,TRUE,FALSE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='5058' AND fi.kildenokkel='aktiv-kommune:afjord' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'27',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:afjord' AND b.ekstern_id='1'),'Møterom 13',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:afjord' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'• 8 personer • Skjerm/Videokonferanse',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='5058' AND fi.kildenokkel='aktiv-kommune:afjord' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs_fasilitet (ressurs_id,fasilitet_id) SELECT r.id,m.fasilitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='fasilitet' AND kk.kode='8' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.fasilitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:afjord' AND r.ekstern_id='8' ON CONFLICT DO NOTHING;
