INSERT INTO kommune (kommunenr,navn,fylkesnavn) VALUES ('5053','Inderøy','Trøndelag') ON CONFLICT (kommunenr) DO NOTHING;
INSERT INTO fagsystem_instans (kildenokkel,type,navn,base_url) VALUES ('aktiv-kommune:inderoy','booking','Aktiv kommune Inderøy','https://inderoy.aktiv-kommune.no') ON CONFLICT (kildenokkel) DO NOTHING;
INSERT INTO kommune_fagsystem_instans (kommune_id,fagsystem_instans_id,type) SELECT k.id, fi.id, fi.type FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='5053' AND fi.kildenokkel='aktiv-kommune:inderoy' ON CONFLICT (kommune_id,fagsystem_instans_id) DO NOTHING;
