INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'24',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:inderoy' AND b.ekstern_id='5'),'Kulturkafeen',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:inderoy' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Kulturkafeen er tilrettelagt for å kunne ha større samlinger i forbindelse med ulike kulturarrangement, konfirmasjoner og matservering. Vi har vårt eget kjøkken i tilknytting til lokalet som gjør det mulig å bestille mat ved enkelte anledninger. Scene (4x6meter) med enkelt lydanlegg. plass til opp mot 200 sittende til bords. Areal ca. 320 kvm',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='5053' AND fi.kildenokkel='aktiv-kommune:inderoy' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'1',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:inderoy' AND b.ekstern_id='1'),'Svømmebasseng',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:inderoy' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Mosvik skole ligger i sentrum av Mosvik ca. 4 km fra Skarnsundbrua. Skolen inneholder både Idrettshall og Svømmebasseng som kan leies. Leietaker må ha godkjent førstehjelpskurs for svømmebassenget. Godkjent førstehjelpskurs må legges som vedlegg i søknaden, søknader uten godkjent førstehjelpskurs blir avslått. Leietaker er ansvarlig for uhell/skader som oppstår på personer og utstyr i forbindelse med aktivitet i bassenget. Søknader om leie blir behandlet i ordinær arbeidstid mandag-fredag kl. 08.00-15.00. Må påberegnes 1 til 2 virkedager svartid.','Svømmebasseng kan bookes hver dag mandag - fredag mellom kl. 16.00 til kl. 22.00 samt lørdag og søndag mellom kl. 09.00 - 22.00. Når det er skolefri kan også svømmebasseng bookes fra kl. 09.00 mandag til fredag. Inngang på østsiden av bygget (mot sjøen).',TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='5053' AND fi.kildenokkel='aktiv-kommune:inderoy' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'2',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:inderoy' AND b.ekstern_id='1'),'Idrettshall',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:inderoy' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Mosvik skole ligger i sentrum av Mosvik ca. 4 km fra Skarnsundbrua. Skolen inneholder både Idrettshall og Svømmebasseng som kan leies. Idrettshall kan bookes hver dag mandag - fredag mellom kl. 16.00 til kl. 22.00 samt lørdag og søndag mellom kl. 10.00 - 22.00. Når det er skolefri kan også idrettshall bookes fra kl. 10.00 mandag til fredag. Inngang på østsiden av bygget (mot sjøen).',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='5053' AND fi.kildenokkel='aktiv-kommune:inderoy' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs_aktivitet (ressurs_id,aktivitet_id) SELECT r.id,m.aktivitet_id FROM ressurs r JOIN fagsystem_instans fi ON fi.id=r.fagsystem_instans_id JOIN kildekode kk ON kk.fagsystem_instans_id=fi.id AND kk.kodetype='aktivitet' AND kk.kode='31' JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' AND m.aktivitet_id IS NOT NULL WHERE fi.kildenokkel='aktiv-kommune:inderoy' AND r.ekstern_id='26' ON CONFLICT DO NOTHING;
