INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'7',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:sogndal' AND b.ekstern_id='2'),'Bibliotek',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:sogndal' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,NULL,NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4640' AND fi.kildenokkel='aktiv-kommune:sogndal' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
INSERT INTO ressurs (fagsystem_instans_id,ekstern_id,kommune_id,bygning_id,navn,lokaletype_id,kapasitet,kapasitet_kilde,beskrivelse,apningstid_tekst,aktiv,bookbar) SELECT fi.id,'9',k.id,(SELECT b.id FROM bygning b JOIN fagsystem_instans f2 ON f2.id=b.fagsystem_instans_id WHERE f2.kildenokkel='aktiv-kommune:sogndal' AND b.ekstern_id='4'),'Klubbhuset',(SELECT m.lokaletype_id FROM kildekode kk JOIN fagsystem_instans f3 ON f3.id=kk.fagsystem_instans_id JOIN kildekode_mapping m ON m.kildekode_id=kk.id AND m.status='godkjent' WHERE f3.kildenokkel='aktiv-kommune:sogndal' AND kk.kodetype='lokaletype' AND kk.kode='1'),NULL,NULL,'Klubbhuset kan brukes til ulike møter og arrangement. Her er det stoler og bord til ca. 30 personer, sittegruppe med sofaer og bord og TV-skjerm du kan koble til PC med HDMI-kabel. I gangen utenfor er det ett stort toalett. Det er ett enkelt utstyrt kjøkken tilgjengelig, med fire kokeplater, stekeovn, panner og gryter, dekketøy til 30 personer, kjøleskap, oppvaskmaskin, vaffeljern, miksmaster og kaffitrakter. Hovedlokalet har universell utforming, loftet er kun mulig å komme til ved å gå trapp. Her er det ukentlig aktvitet med blant annet "Sterk og Stødig", linedance, ungdomsklubb og grupper fra idrettslaget.',NULL,TRUE,TRUE FROM kommune k, fagsystem_instans fi WHERE k.kommunenr='4640' AND fi.kildenokkel='aktiv-kommune:sogndal' ON CONFLICT (fagsystem_instans_id,ekstern_id) DO UPDATE SET navn=EXCLUDED.navn;
